INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (2047, N'055', N'Vệ sinh chuồng trại giống gia cầm', N'IV', N'Làm việc trong môi trường bụi, bẩn, hôi thối công việc nặng nhọc, tiếp xúc với nhiều loại nấmvà vi sinh vật gây bệnh.                                                                                   ', 35);
