INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3128, N'155', N'Điều trị người nhiễm HIV, AIDS', N'VI', N'Công việc rất nguy hiểm, nguy cơ lây nhiễm cao bệnh không có khả năng cứu chữa, căng thẳng bệnh nhân thần kinh tâm lý.                                                                                  ', 56);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3129, N'156', N'Phục vụ người nhiễm HIV, AIDS', N'VI', N'Công việc rất nguy hiểm, nguy cơ lây nhiễm cao bệnh không có khả năng cứu chữa, căng thẳng bệnh nhân thần kinh tâm lý.                                                                                  ', 56);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3130, N'157', N'Giải phẫu bệnh lý đại thể', N'VI', N'Thường xuyên tiếp xúc với xác chết, các vi khuẩn có hại và các hoá chất độc, căng thẳng thần kinh tâm lý.                                                                                               ', 56);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3131, N'158', N'Liệm xác', N'VI', N'Thường xuyên tiếp xúc với xác chết, các vi khuẩn có hại và các hoá chất độc, căng thẳng thần kinh tâm lý.                                                                                               ', 56);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3132, N'159', N'ướp xác', N'VI', N'Thường xuyên tiếp xúc với xác chết, các vi khuẩn có hại và các hoá chất độc, căng thẳng thần kinh tâm lý.                                                                                               ', 56);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3133, N'160', N'Khám nghiệm tử thi', N'VI', N'Thường xuyên tiếp xúc với xác chết, các vi khuẩn có hại và các hoá chất độc, căng thẳng thần kinh tâm lý.                                                                                               ', 56);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3134, N'161', N'Vệ sinh nhà xác', N'VI', N'Thường xuyên tiếp xúc với xác chết, các vi khuẩn có hại và các hoá chất độc, căng thẳng thần kinh tâm lý.                                                                                               ', 56);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3135, N'001', N'Hiệu chỉnh lò hơi nhà máy nhiệt điện', N'IV', N'Làm việc cạnh các thiết bị có nhiệt độ cao từ 160 độ C đến 540 độ C, chịu tác động của tiếng ồn và bụi.                                                                                                 ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3136, N'002', N'Vận hành máy nghiền than trong nhà máy nhiệt điện', N'IV', N'Chịu tác động của nóng, tiếng ồn và bụi than có nồng độ cao.                                                                                                                                            ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3137, N'003', N'Vận hành băng tải trong nhà máy nhiệt điện', N'IV', N'Công việc thủ công nặng nhọc, chịu tác động của nóng, ồn, và bụi than có nồng độ cao.                                                                                                                   ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3138, N'004', N'Xúc và gom than trong nhà máy nhiệt điện', N'IV', N'Công việc thủ công nặng nhọc, chịu tác động của nóng, ồn, và bụi than có nồng độ cao.                                                                                                                   ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3139, N'005', N'Vận hành máy bơm dầu đốt lò nhà máy nhiệt điện (Vânh hành nhà dầu)', N'IV', N'Thường xuyên tiếp xúc với dầu mỡ, tiếng ồn và nhiệt độ cao.                                                                                                                                             ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3140, N'006', N'Vận hành hệ thống thải xỉ nhà máy nhiệt điện (bơm thải xỉ, khử bụi, tống tưới...)', N'IV', N'Thường xuyên tiếp xúc với nóng, độ ồn cao và nồng độ bụi vượt tiêu chuẩn cho phép.                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3141, N'007', N'Kiểm nghiệm (trực chính, trực phụ) trong nhà máy nhiệt điện', N'IV', N'Thường xuyên tiếp xúc với nóng, rung, độ ồn cao và nồng độ bụi vượt tiêu chuẩn cho phép.                                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3142, N'008', N'Sửa chữa các thiết bị điện trong nhà máy điện', N'IV', N'Tư thế lao động gò bó, ảnh hương của ồn rung và bụi.                                                                                                                                                    ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3143, N'009', N'Lái quang lật toa than', N'IV', N'Thường xuyên làm việc ở môi trường nóng, bụi, ồn vượt tiêu chuẩn cho phép.                                                                                                                              ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3144, N'010', N'Móc nối toa xe than trong nhà máy nhiệt điện', N'IV', N'Làm việc ngoài trời, chịu tác động của môi trường (nóng, lạnh, gió...), tiếng ồn và nồng độ bụi than cao.                                                                                               ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3145, N'011', N'Công nhân xúc xỉ đuôi lò nhà máy nhiệt điện', N'IV', N'Công việc nặng nhọc, đơn điệu; thường xuyên tiếp xúc với nóng, bụi.                                                                                                                                     ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3146, N'012', N'Vận hành tua bin khí', N'IV', N'Chịu tác động của rung, nóng và tiếng ồn vượt tiêu chuẩn cho phép.                                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3147, N'013', N'Hàn và mài cánh hướng nước nhà máy thuỷ điện', N'IV', N'Làm việc trong hầm sâu, thiếu dưỡng khí; tiếp xúc thường xuyên với tiếng ồn, nhiệt độ cao, hơi khí độc và bụi thép.                                                                                     ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3148, N'014', N'Hàn và mài cánh tua bin nhà máy thuỷ điện', N'IV', N'Làm việc trong hầm sâu, thiếu dưỡng khí; tiếp xúc thường xuyên với tiếng ồn, nhiệt độ cao, hơi khí độc và bụi thép.                                                                                     ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3149, N'015', N'Quản lý đường dây 110KV đến dưới 500KV', N'IV', N'Thường xuyên lưu đông theo đường dây, qua các vùng địa hình, khí hậu phức tạp; tiếp xúc với điện từ trường cao, ảnh hưởng đến sức khoẻ.                                                                 ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3150, N'016', N'Vận hành đường dây 110KV đến dưới 500KV', N'IV', N'Thường xuyên lưu đông theo đường dây, qua các vùng địa hình, khí hậu phức tạp; tiếp xúc với điện từ trường cao, ảnh hưởng đến sức khoẻ.                                                                 ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3151, N'017', N'Vệ sinh công nghiệp trạm biến áp 500KVA', N'IV', N'Công việc đơn điệu; tiếp xúc với bụi bẩn, điện từ trường cao ảnh hưởng đến sức khoẻ và nguy hiểm.                                                                                                       ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3152, N'018', N'Sản xuất hòm công tơ vật liệu Composit', N'IV', N'Tiếp xúc với nóng, hoá chất nồng độ cao, gây khó thở, mệt mỏi.                                                                                                                                          ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3153, N'019', N'Sửa chữa máy biến áp có công suất từ 200KVA trở lên', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với dầu mỡ, môi trường có nhiệt độ cao.                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3154, N'020', N'Sấy máy biến áp có công suất từ 200KVA trở lên', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với dầu mỡ, môi trường có nhiệt độ cao.                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3155, N'021', N'Vận hành máy bện cáp nhôm', N'IV', N'ảnh hưởng trực tiếp của bụi nhôm và tiếng ồn cao.                                                                                                                                                       ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3156, N'022', N'Vận hành máy đúc cột điện bê tông ly tâm', N'IV', N'Chịu tác động của tiếng ồn, rung và bụi.                                                                                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3157, N'023', N'Sản xuất vật liệu cách điện', N'IV', N'Công việc nặng nhọc; tiếp xúc với nhiệt độ cao và hoá chất độc hại (Phenol, Formalin, Amoniac...) nồng độ cao.                                                                                          ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3158, N'024', N'Vận hành máy trong nhà máy điện', N'IV', N'Công việc phức tạp, đi lại nhiều, ảnh hưởng của ồn, nồng độ bụi rất cao.                                                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3159, N'025', N'Vận hành điện trong nhà máy điện', N'IV', N'Công việc phức tạp, đi lại nhiều, ảnh hưởng của ồn, nồng độ bụi rất cao.                                                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3160, N'026', N'Trưởng kíp vận hành kiểm nhiệt nhà máy nhiệt điện', N'IV', N'Đi lại nhiều, ảnh hưởng của nóng, ồn và bụi vượt tiêu chuẩn cho phép nhiều lần.                                                                                                                         ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3161, N'027', N'Vận hành bơm tuần hoàn nhà máy nhiệt điện', N'IV', N'Làm việc dưới hầm ẩm ướt, chịu tác động liên tục của tiếng ồn cao.                                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3162, N'028', N'Trưởng kíp vận hành than nhà máy nhiệt điện', N'IV', N'ảnh hưởng của ồn và bụi nồng độ cao.                                                                                                                                                                    ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3163, N'029', N'Vận hành thiết bị phụ tuốc bin nhà máy điện', N'IV', N'Tiếp xúc thường xuyên với rung và tiếng ồn rất cao.                                                                                                                                                     ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3164, N'030', N'Vận hành máy nén khí áp lực từ 8kg/cm2 trở lên', N'IV', N'ảnh hưởng của rung và tiếng ồn rất cao.                                                                                                                                                                 ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3165, N'031', N'Sửa chữa van hơi nhà máy nhiệt điện', N'IV', N'Nơi làm việc chật hẹp, tư thế làm việc gò bó, ảnh hưởng của nóng và bụi nồng độ rất cao.                                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3166, N'032', N'Thí nghiệm thiết bị điện', N'IV', N'ảnh hưởng của điện từ trường cao, thường xuyên tiếp xúc với điện cao áp nên rất nguy hiểm đến tính mạng.                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3167, N'033', N'Thí nghiệm điện cao áp', N'IV', N'ảnh hưởng của điện từ trường cao, thường xuyên tiếp xúc với điện cao áp nên rất nguy hiểm đến tính mạng.                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3168, N'034', N'Sửa chữa thiết bị tự động nhà máy điện', N'IV', N'ảnh hưởng của bụi, rung và ồn cao.                                                                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3169, N'035', N'Sửa chữa điện trong nhà máy điện', N'IV', N'Tư thế làm việc gò bó, ảnh hưởng của ồn, rung và bụi.                                                                                                                                                   ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3170, N'036', N'Sửa chữa kiểm nhiệt nhà máy nhiệt điện', N'IV', N'Tiếp xúc thường xuyên với nóng, rung và ồn cao.                                                                                                                                                         ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3171, N'037', N'Sửa chữa băng tải than', N'IV', N'Nơi làm việc bẩn và rất bụi, tư thế làm việc gò bó.                                                                                                                                                     ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3172, N'038', N'Vệ sinh công nghiệp nhà máy nhiệt điện', N'IV', N'Công việc thủ công, ảnh hưởng của nóng, ồn và nồng độ bụi rất cao.                                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3173, N'039', N'Vận hành cửa nhận nước trạm bơm bờ trái nhà máy thuỷ điện Hoà Bình', N'IV', N'Công việc nặng nhọc, nơi làm việc ẩm ướt, trơn dầu mỡ, ảnh hưởng của ồn cao.                                                                                                                            ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3174, N'040', N'Vận hành thiết bị đóng mở cảnh phải đập tràn nhà máy thuỷ điện Hoà Bình', N'IV', N'Công việc nặng nhọc, nơi làm việc ẩm ướt, trơn dầu mỡ, ảnh hưởng của ồn cao.                                                                                                                            ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3175, N'041', N'Sửa chữa ắc quy trong hang hầm nhà máy điện', N'IV', N'Nơi làm việc thiếu dưỡng khí, thường xuyên tiếp xúc với axít H2SO4, CO2.                                                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3176, N'042', N'Phóng nạp ắc quy trong hang hầm nhà máy điện', N'IV', N'Nơi làm việc thiếu dưỡng khí, thường xuyên tiếp xúc với axít H2SO4, CO2.                                                                                                                                ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3177, N'043', N'Sửa chữa nén khí', N'IV', N'Nơi làm việc chật hẹp, trơn dầu mỡ, ảnh hưởng của ồn cao.                                                                                                                                               ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3178, N'044', N'Sửa chữa thiết bị trạm biến thế', N'IV', N'Nơi làm việc chật hẹp, trơn dầu mỡ, ảnh hưởng của ồn cao.                                                                                                                                               ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3179, N'045', N'Thí nghiệm hoá nhà máy điện', N'IV', N'Thường xuyên tiếp xúc với dầu mỡ, các hoá chất độc, ồn và bụi.                                                                                                                                          ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3180, N'046', N'Lọc dầu máy biến thế trong hang hầm', N'IV', N'Nơi làm việc chật hẹp, thường xuyên tiếp xúc với dầu mỡ, ảnh hưởng của ồn cao.                                                                                                                          ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3181, N'047', N'Sửa chữa cơ phụ trong hang hầm nhà máy điện', N'IV', N'Nơi làm việc kém thông thoáng, tư thế gò bó, ảnh hưởng của ồn cao.                                                                                                                                      ', 57);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (3182, N'048', N'Sửa chữa điện phụ trong hang hầm nhà máy điện', N'IV', N'Nơi làm việc kém thông thoáng, tư thế gò bó, ảnh hưởng của ồn cao.                                                                                                                                      ', 57);
