INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9786, N'001481', N'Làm việc trên xuồng tuần tra, kiểm soát vùng nước quân sự.', N'V', N'Làm việc ngoài trời nắng nóng, bức xạ nhiệt cao, trong môi trường chật hẹp, ấm ướt, trơn trượt, đi lại không đúng tư thế, rung xóc, tiếng ồn, tiếp xúc các loại dầu mỡ (diezel,…) trong điều kiện sóng gió phức tạp. Làm việc cả ngày và đêm với sự tập trung cao, luôn trong tình trạng căng thẳng tâm thần kinh do vừa điều khiển xuồng, vừa quan sát vùng nước, vừa phải xử lý các tình huống, xua đuổi mục tiêu.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9802, N'001497', N'Lái xe phục vụ nghi lễ, tang lễ cấp Nhà nước.', N'IV', N'Công việc lưu động, nguy hiểm, nặng nhọc, chịu tác động của của ồn và rung, thực hiện nhiệm vụ trong điều kiện thường xuyên đi theo đoàn, áp lực, căng thẳng thị giác, thần kinh, áp lực bảo đảm an toàn giao thông, cự ly và tốc độ khi hành quân cơ giới.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9804, N'747', N'Khai thác, vận hành, sửa chữa ra đa quan sát hải quân', NULL, NULL, 11);
