INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9815, N'758', N'Vận hành trạm rửa xe', NULL, NULL, 28);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9816, N'759', N'Kỹ thuật đầu tư', NULL, NULL, 29);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9817, N'760', N'Công nhân vận hành trạm rửa xe tự động', NULL, NULL, 121);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9818, N'761', N'NV phục vụ', NULL, NULL, 121);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9819, N'762', N'Hậu cần', NULL, NULL, 121);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9820, N'763', N'Kế hoạch tổng hợp', NULL, NULL, 1);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9821, N'764', N'Lái xe từ 7,5T đến dưới 16,5T', NULL, NULL, 1);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9822, N'765', N'Phụ xe ô tô', NULL, NULL, 25);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9823, N'766', N'Lái xe ô tô khách từ 40 ghế đến dưới 80 ghế', NULL, NULL, 25);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9824, N'767', N'Khai thác than lộ thiên', NULL, NULL, 29);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9825, N'768', N'Lái xe ô tô mỏ', NULL, NULL, 29);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9826, N'769', N'Lái xe vận tải có trọng tải từ 7,5 tấn đến dưới 16,5 tấn', NULL, NULL, 29);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9827, N'770', N'Lao động tiền lương', NULL, NULL, 29);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9828, N'771', N'vận hành máy sấy phun', NULL, NULL, 41);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9829, N'772', N'Kế toán vật tư', NULL, NULL, 26);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9830, N'773', N'Thợ sửa chữa lắp đặt', NULL, NULL, 1);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9831, N'774', N'sơn', NULL, NULL, 48);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9832, N'775', N'Thợ sơn', NULL, NULL, 26);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9833, N'776', N'Lắp ráp điện tử', NULL, NULL, 48);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9834, N'777', N'Nhân viên chuyên môn, nghiệp vụ', NULL, NULL, 48);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9835, N'778', N'Sửa chữa VTĐ', NULL, NULL, 48);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9836, N'000958', N'Sửa chữa anten ra đa, ra đa tên lửa.', N'VI', N'Ảnh hưởng điện từ trường siêu cao tần vượt tiêu chuẩn cho phép nhiều lần, công việc nặng nhọc, nguy hiểm căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9837, N'000959', N'Lái máy bay chiến đấu siêu âm, giáo viên huấn luyện bay; phi công bay thử.', N'VI', N'Nặng nhọc, nguy hiểm, hệ số quá tải lớn, thiếu dưỡng khí, ảnh hưởng điện từ trường siêu cao tần, ồn, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9838, N'000960', N'Tổ lái máy bay vận tải quân sự, trực thăng vũ trang, máy bay trinh sát.', N'VI', N'Nặng nhọc, nguy hiểm, ảnh hưởng điện từ trường siêu cao tần, ồn, căng thẳng thẳng kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9839, N'000961', N'Sản xuất, khôi phục chất O, chất G (phục vụ chiến đấu của tên lửa).', N'VI', N'Thường xuyên tiếp xúc với các chất độc hại, chất O, chất G, rất nguy hiểm.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9840, N'000962', N'Trinh sát không gian mạng.', N'VI', N'Làm việc trong phòng kín, chịu tác động của bức xạ màn hình và điện từ trường cao tần ở mức độ cao liên tục; tư thế làm việc gò bó, căng thẳng thần kinh tâm lý, thị giác.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9841, N'000963', N'Phòng thủ mạng, ứng cứu sự cố an toàn thông tin.', N'VI', N'Làm việc trong nhiều điều kiện môi trường khác nhau, chịu tác động của bức xạ màn hình và điện từ trường cao tần ở mức độ cao, liên tục; tư thế làm việc gò bó, căng thẳng thần kinh tâm lý, thị giác.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9842, N'000964', N'Tấn công mạng.', N'VI', N'Làm việc trong phòng kín, chịu bức xạ màn hình và điện từ trường cao tần ở mức độ cao; tư thế làm việc gò bó, cường độ cao, áp lực lớn, căng thẳng thị giác, thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9843, N'000965', N'Tác chiến thông tin.', N'VI', N'Làm việc trong phòng kín, chịu tác động bức xạ màn hình và điện từ trường cao tần; tư thế làm việc gò bó, lao động trí óc căng thẳng, áp lực lớn, căng thẳng thị giác, thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9844, N'000966', N'Vận hành, bảo dưỡng, hiệu chỉnh, sửa chữa thiết bị xe, đài, điều khiển tên lửa, xe đài tác chiến điện tử.', N'V', N'Tư thế gò bó, ảnh hưởng điện từ trường siêu cao tần vượt tiêu chuẩn cho phép nhiều lần.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9845, N'000967', N'Điều khiển (hệ phát lệnh, hệ thống nhiễu, hệ tọa độ, máy hỏi, quang truyền hình) tên lửa, ra đa tác chiến điện tử.', N'V', N'Thường xuyên tiếp xúc với điện từ trường siêu cao tần, nơi làm việc chật hẹp, nóng, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9846, N'000968', N'Lắp ráp, kiểm tra, hiệu chỉnh, sửa chữa đạn, tên lửa.', N'V', N'Công việc nguy hiểm, tiếp xúc hóa chất độc tập trung chú ý cao, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9847, N'000969', N'Vận hành máy nén khí nạp vào tên lửa, khí tài tác chiến điện tử.', N'V', N'Công việc nặng nhọc, nguy hiểm, ồn, bụi.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9848, N'000970', N'Vận hành kiểm tra, sửa chữa hiệu chỉnh ra đa, ra đa tác chiến điện tử.', N'V', N'Ảnh hưởng điện từ trường siêu cao tần, tia ron ghen, hiệu ứng bề mặt, ồn.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9849, N'000971', N'Kíp điều khiển pháo phòng không tự hành (Zey 23...).', N'V', N'Làm việc trong xe, nóng, chật hẹp, gò bó, ồn, rung, xóc, ảnh hưởng điện từ trường siêu cao tần.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9850, N'000972', N'Lái máy bay trinh sát cánh mềm.', N'V', N'Nguy hiểm, ảnh hưởng điện từ trường, ồn, căng thẳng thần kinh tâm lý', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9851, N'000973', N'Nhảy dù (làm nhiệm vụ chiến đấu, tìm kiếm, cấp cứu).', N'V', N'Công việc nặng nhọc, nguy hiểm, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9852, N'000974', N'Kỹ thuật cơ vụ bảo đảm an toàn bay ở các sân bay quân sự.', N'V', N'Làm việc nài trời, ảnh hưởng tiếng ồn lớn vượt tiêu chuẩn cho phép nhiều lần, điện từ trường.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9853, N'000975', N'Sửa chữa máy bay phản lực tại các trạm, xưởng sửa chữa.', N'V', N'Công việc nặng nhọc, chịu tác động tiếng ồn lớn vượt tiêu chuẩn cho phép nhiều lần và hóa chất độc hại.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9854, N'000976', N'Dẫn đường bay ở các trạm ra đa sân bay.', N'V', N'Ảnh hưởng tiếng ồn lớn, điện từ trường siêu cao tần, bức xạ màn hình ra đa, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9855, N'000977', N'Pháo thủ bệ đạn tên lửa, pháo thủ Pháo phòng không tầm trung.', N'V', N'Thường xuyên làm việc nài trời, lao động nặng nhọc, nóng, nắng.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9856, N'000978', N'Làm việc (theo kíp) trên xe huấn luyện, chiến đấu tên lửa Phòng không; hệ lập lệnh trong xe điều khiển tên lửa.', N'V', N'Nơi làm việc chật hẹp, nóng, thiếu dưỡng khí, căng thẳng thần kinh tâm lý, ảnh hưởng của sóng siêu cao tần.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9857, N'000979', N'Sản xuất, chế tạo keo (đặc thù quân sự) phục vụ sửa chữa, bảo quản kỹ thuật phòng không.', N'V', N'Thường xuyên tiếp xúc với hoá chất độc hại, chịu ảnh hưởng của tiếng ồn cao.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9858, N'000980', N'Sửa chữa các tổ hợp điều khiển vũ khí hàng không (ra đa vô tuyến, hệ thống quang điện tử, ra đa ngắm bắn).', N'V', N'Ảnh hưởng sóng siêu cao tần, sóng điện tử, ồn, nóng, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9859, N'000981', N'Khai thác, sử dụng, sửa chữa (kíp làm việc) trong xe tên lửa phòng không tầm thấp.', N'V', N'Công việc nặng nhọc, tư thế làm việc gò bó, chật hẹp, nóng, tiếp xúc sóng siêu cao tần, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9860, N'000982', N'Nghiên cứu, hiệu chỉnh máy phát và đường truyền sóng của ra đa quân sự các loại.', N'V', N'Ảnh hưởng điện từ trường siêu cao tần, điện cao áp công suất lớn, công suất lọt của máy phát rất lớn.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9861, N'000983', N'Vệ sinh, bảo vệ đường băng thu gấp dù phục vụ các chuyến bay.', N'V', N'Làm việc nài trời, nặng nhọc, tiếp xúc ồn, bụi đường băng.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9862, N'000984', N'Dự báo quan trắc khí tượng trực tiếp ở sân bay và phục vụ bay; không ảnh kiểm tra khách quan, trinh sát điện tử, gây nhiễu.', N'V', N'Ảnh hưởng điện từ trường cao tần, ồn, bụi.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9863, N'000985', N'Chế tạo, khai thác, vận hành buồng tập lái máy bay quân sự.', N'V', N'Nơi làm việc chật hẹp, tư thế gò bó, nóng, căng thẳng thần kinh, tiếp xúc điện từ trường.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9864, N'000986', N'Vận hành hệ thống tự động hoá chỉ huy tác chiến điện tử cơ động.', N'V', N'Trực tiếp tiếp xúc sóng điện từ, vận hành cơ cấu xe chuyên dụng, môi trường làm việc chật hẹp, nóng bức, căng thẳng thần kinh, mệt mỏi, tiêu hao sức khoẻ lớn. Thường xuyên cơ động triển khai nài hiện trường, triển khai các thiết bị trên cao.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9865, N'000987', N'Nghiên cứu, thử nghiệm các loại khí tài như: ra đa, sô na, thủy âm, quang điện tử, laser, tác chiến điện tử, vũ khí điện từ trường, ngụy trang, nghi trang.', N'V', N'Chịu ảnh hưởng của sóng siêu cao tần tạo ra từ các thiết bị chưa được chế tạo hoàn thành (đang trong giai đoạn thử nghiệm) căng thẳng thần kinh tâm lý ảnh hưởng tới sức khoẻ sinh học.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9866, N'000988', N'Quản lý, điều hành sở chỉ huy tác chiến điện tử.', N'V', N'Tiếp xúc khí tài trinh sát, chịu ảnh hưởng của bức xạ điện từ, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9867, N'000989', N'Kíp huấn luyện Pháo phòng không và Đài điều khiển trung tâm.', N'V', N'Người lao động làm việc không theo giờ cố định. Công việc đặc biệt nguy hiểm, thường xuyên làm việc nài trời, lao động nặng nhọc, nóng, nắng, tiếng ồn, hơi thuốc súng yêu cầu tập trung chú ý cao, căng thẳng thần kinh tâm lý mức độ cao.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9868, NULL, N'Vận hành, quản trị hệ thống, nghiên cứu, phát triển ứng dụng, hướng dẫn viên làm việc trên các hệ thống mô phỏng không quân.', N'V', N'Tính chất công việc căng thẳng, cường độ làm việc lớn, có mức độ bức xạ nguy hại cao, phải tập trung cao độ, thường xuyên tiếp xúc trực tiếp với hệ thống máy móc, máy chiếu chuyên dụng chiếu thẳng vào đầu trong thời gian dài. Thường xuyên tiếp xúc với tiếng ồn lớn, sóng vô tuyến của hệ thống đài trạm, ra đa. Không gian làm việc chật hẹp, gò bó kéo dài trong các hệ thống mô phỏng.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9869, N'000991', N'Nghiên cứu, chế thử, thử nghiệm vũ khí, trang bị tác chiến không gian mạng.', N'V', N'Làm việc trong phòng kín, thường xuyên liên tục thao tác trên máy tính, chịu bức xạ màn hình và điện từ trường cao tần, ánh sáng xanh, tư thế làm việc gò bó, căng thẳng thần kinh, tâm lý, thị giác.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9870, NULL, N'Trực tiếp khai thác, điều khiển máy bay không người lái.', N'V', N'Làm việc không theo khung giờ cố định, làm việc trong điều kiện tiếng ồn vượt ngưỡng cho phép; liên tục chịu ảnh hưởng trực tiếp của môi trường: nhiệt độ cao, nắng nóng...; không gian làm việc chật hẹp trong buồn điều khiển; chịu ảnh hưởng trực tiếp của bức xạ màn hình, sóng vô tuyến của hệ thống đài trạm, SATCOM, ra đa... ảnh hưởng đến thị lực, tinh thần căng thẳng.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9871, NULL, N'Trực tiếp bảo dưỡng, sửa chữa máy bay không người lái.', N'V', N'Thường xuyên làm việc trong điều kiện tiếng ồn vượt ngưỡng cho phép; liên tục chịu ảnh hưởng trực tiếp của môi trường: nhiệt độ cao, nắng nóng... thường xuyên tiếp xúc với hóa chất, vật liệu composite, xăng dầu, dầu nhớt đặc chủng trong quá trình bảo quản, bảo dưỡng, sửa chữa máy bay; liên tục chịu ảnh hưởng của sóng vô tuyến, sóng điện từ của hệ thống trạm thông tin liên lạc, ra đa, SATCOM...', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9872, N'000994', N'Sử dụng tên lửa phòng không vác vai.', N'IV', N'Công việc nặng nhọc, độc hại, nguy hiểm.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9873, N'000995', N'Sữa chữa thiết bị xe kiểm tra đạn tên lửa, ra đa.', N'IV', N'Ảnh hưởng điện từ trường cao tần, tư thế làm việc gò bó, chật hẹp, nóng.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9874, N'000996', N'Điều khiển moóc kéo, chở đạn tên lửa, moóc nạp khí cao áp.', N'IV', N'Công việc nặng nhọc, ồn, bụi, tiếp xúc khí độc, nguy hiểm.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9875, N'000997', N'Sử dụng khí tài quang học.', N'IV', N'Căng thẳng thần kinh, thị giác, chịu tác động hóa chất độc hại.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9876, N'000998', N'Sử dụng, sửa chữa máy đo cao tần, máy đo hiện sóng, đồng hồ và máy đo cao áp.', N'IV', N'Ảnh hưởng điện từ trường siêu cao tần, tiếp xúc hơi khí độc.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9877, N'000999', N'Bảo đảm khí tài quân giới trực tiếp ở sân bay.', N'IV', N'Làm việc nài trời, tiếp xúc hóa chất độc hại, căng thẳng thị giác.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9878, N'001000', N'Phục vụ trên máy bay (thả hàng, cẩu tời...).', N'IV', N'Tiếng ồn lớn, nguy hiểm, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9879, N'001001', N'Làm việc trong xe thông tin sân bay; hàng y phục vụ chuyến bay; chỉ huy ban bay.', N'IV', N'Nơi làm việc chật hẹp, nóng, chịu tác động tiếng ồn lớn và điện từ trường.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9880, N'001002', N'Lái xe cứu hỏa, xe tra nạp xăng, dầu, khí, xe điện phục vụ bay ở sân bay.', N'IV', N'Nóng, tiếp xúc hóa chất độc, ồn.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9881, N'001003', N'Sửa chữa máy bay cánh quạt tại các trạm, xưởng sửa chữa.', N'IV', N'Công việc nặng nhọc, tiếp xúc xăng, dầu, hóa chất độc và tiếng ồn.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9882, N'001004', N'Nhân viên truyền số liệu (VQ-98-01) ở các sở chỉ huy, trạm ra đa.', N'IV', N'Tiếp xúc sóng siêu cao tần, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9883, N'001005', N'Vận hành các loại xe đặc chủng tại sân đỗ máy bay quân sự.', N'IV', N'Làm việc nài trời, nóng, ồn, tiếp xúc với điện từ trường.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9884, N'001006', N'Sản xuất khí Ni tơ, ô xy (nạp vào xe khí để khởi động máy bay).', N'IV', N'Tiếp xúc với chất độc, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9885, N'001007', N'Sản xuất, chế tạo các loại đệm cao su, đệm phi kim loại phục vụ quân sự.', N'IV', N'Nơi làm việc nóng, ồn, tiếp xúc với hoá chất độc.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9886, N'001008', N'Sản xuất sơn đặc thù phục vụ cho sửa chữa máy bay quân sự.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9887, N'001009', N'Chế tạo, lắp ráp các loại mục tiêu bay phục vụ huấn luyện.', N'IV', N'Tiếp xúc với hoá chất và các loại vật liệu độc hại.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9888, N'001010', N'Vận hành máy nổ từ 8 KW trở lên ở đơn vị chiến đấu.', N'IV', N'Chịu tiếng ồn lớn, căng thẳng thần kinh tâm lý, tiếp xúc với dầu, mỡ.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9889, N'001011', N'Nhân viên thu, nghe tình báo trên không ở các sở chỉ huy (tiêu đồ 9x9, 5x5).', N'IV', N'Nơi làm việc chật hẹp, tư thế gò bó, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9890, N'001012', N'Khai thác, sử dụng, sửa chữa tên lửa Phòng không tầm thấp.', N'IV', N'Công việc nặng nhọc, nguy hiểm, căng thẳng thần kinh tâm lý, tiếp xúc hoá chất độc.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9891, N'001013', N'Giảng viên huấn luyện thực hành tên lửa phòng không tầm trung, tầm cao, thực hành bệ đạn tên lửa.', N'IV', N'Chịu ảnh hưởng điện từ trường siêu cao tần, làm việc nài trời.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9892, N'001014', N'Giảng viên huấn luyện thực hành pháo, pháo phòng không, ra đa, pháo thủ, pháo phòng không tầm thấp.', N'IV', N'Căng thẳng thần kinh tâm lý, tiêu hao năng lượng lớn, làm việc nài trời.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9893, N'001015', N'Làm công tác quản lý và trực tiếp điều hành tại trung tâm quản lý điều hành bay quốc gia và các sở chỉ huy không quân.', N'IV', N'Chịu tác động của bức xạ nhiệt, bức xạ điện từ, ồn, căng thẳng thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9894, N'001016', N'Kíp trực quản lý hoạt động bay vùng trời quốc gia.', N'IV', N'Thường xuyên thao tác trên máy vi tính, chịu tác động của bức xạ điện từ, căng thẳng thần kinh, thị giác.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9895, N'001017', N'Giảng viên huấn luyện thực hành tên lửa phòng không tầm thấp.', N'IV', N'Làm việc nài trời, công việc nặng nhọc, nguy hiểm.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9896, N'001018', N'Kiểm định phần mềm và dữ liệu; hệ thống và thiết bị công nghệ thông tin.', N'IV', N'Làm việc trong môi trường thiếu ánh sáng, thiếu dưỡng khí, tác động của rung, lắc, tiếng ồn, căng thẳng thị giác, mệt mỏi thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9897, N'001019', N'Tiêu chuẩn - Đo lường - Chất lượng hệ thống và thiết bị công nghệ thông tin.', N'IV', N'Chịu tác động, ảnh hưởng của bức xạ điện từ trường, tư thế làm việc gò bó, thiếu ánh sách, thiếu dưỡng khí, tác động rung, lắc, căng thẳng thị giác, thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9898, N'001020', N'Đảm bảo kỹ thuật công nghệ thông tin; sửa chữa, bảo dưỡng trang bị công nghệ thông tin.', N'IV', N'Làm việc trong điều kiện môi trường khác nhau, chịu tác động của bức xạ màn hình, các thiết bị điện tử và điện từ trường cao tần, tư thế làm việc gò bó, căng thẳng thị giác, mệt mỏi thần kinh tâm lý.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9899, N'001021', N'Quản lý, khai thác vận hành trung tâm dữ liệu, trạm máy chủ công nghệ thông tin.', N'IV', N'Công việc nặng nhọc, căng thẳng thị giác, thần kinh tâm lý; làm việc trong phòng kín, chịu ảnh hưởng bức xạ điện từ trường, thiếu ánh sáng, thiếu dưỡng khí.', 2);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9900, N'001022', N'Sỹ quan, thuyền viên làm việc trong tàu ngầm quân sự.', N'VI', N'Làm việc trong điều kiện chật hẹp, gò bó, thiếu dưỡng khí, áp suất cao, tiêu hao năng lượng lớn, mệt mỏi thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9901, N'001023', N'Sỹ quan, thuyền viên làm việc trên tàu chiến.', N'VI', N'Công việc nài trời, nặng nhọc, nguy hiểm, rung, ồn lớn, tư thế gò bó, mệt mỏi thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9902, N'001024', N'Thợ lặn.', N'VI', N'Công việc nặng nhọc, nguy hiểm, chịu áp suất cao, thiếu dưỡng khí.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9903, N'001025', N'Bộ đội phòng thủ ở Trường Sa và DKl.', N'VI', N'Công việc nặng nhọc, nguy hiểm, nơi làm việc ẩm ướt, chịu tác động của thời tiết, sóng gió dễ nhiễm khuẩn, nhiễm bệnh.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9904, N'001026', N'Thợ ụ (âu) đà sửa chữa tàu quân sự.', N'VI', N'Thường xuyên phải lặn, công việc nặng nhọc, nguy hiểm, tư thế lao động gò bó, nóng, ẩm ướt, thiếu dưỡng khí, thường xuyên tiếp xúc dầu mỡ.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9905, N'001027', N'Sỹ quan, thuyền viên làm việc trên tàu quân sự ở biển xa và khảo sát đo đạc trên biển.', N'VI', N'Chịu ảnh hưởng của sóng lớn, rung lắc, thời tiết khắc nghiệt, làm việc trong hầm bảo quản lạnh, môi trường ô nhiễm do hải sản phân huỷ.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9906, NULL, N'Bảo quản, sửa chữa chống ăn mòn các công trình nhà giàn nài biển.', N'VI', N'Công việc nặng nhọc, nguy hiểm chịu tác động của bụi, hoá chất độc, ồn, rung, sóng và gió.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9907, N'001029', N'Sỹ quan, thuyền viên làm việc trên tàu quân sự và khảo sát đo đạc trên biển.', N'VI', N'Chịu ảnh hưởng của sóng lớn, rung lắc, thời tiết khắc nghiệt.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9908, NULL, N'Vận hành, khai thác sử dụng, bảo dưỡng trang thiết bị lặn, tàu lặn cứu nạn tàu ngầm.', N'VI', N'Công việc đặc thù, rất nguy hiểm, làm việc ở độ sâu lớn, cường độ cao, trong môi trường kín, chật hẹp, thiếu ánh sáng, thiếu dưỡng khí, chịu áp lực lớn, dễ xảy ra mất an toàn; thường xuyên chịu tác động tiếng ồn, rung lắc, sóng điện từ, căng thẳng thần kinh, tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9909, NULL, N'Huấn luyện thực hành lặn, lặn sửa chữa, lặn thoát hiểm, lặn cứu hộ tàu ngầm.', N'VI', N'Công việc nặng nhọc, nguy hiểm (áp suất lớn), thiếu dưỡng khí, tiêu hao năng lượng lớn, điều kiện huấn luyện căng thẳng, tư thế hoạt động gò bó, chật hẹp; căng thẳng thần kinh tâm lý. Tiếp xúc trực tiếp với chất tái sinh không khí O3 hoặc Vôi Soda (có thể gây bỏng đường hô hấp khi bị nước tràn vào bình tái sinh).', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9910, NULL, N'Sửa chữa, bảo dưỡng tàu ngầm: điện; máy; cơ khí; van ống; thân vỏ - khoang két; vũ khí; khí tài - điện tử; trang trí; mạ chi tiết tàu ngầm.', N'VI', N'Làm việc trong điều kiện khắc nghiệt, vi khí hậu nóng đặc biệt là làm việc trong khoang tầu ngầm kín, thông khí kém, tiếp xúc với tiếng ồn lớn từ hoạt động sửa chữa; rung do thiết bị sửa chữa cầm tay; nồng độ bụi chứa silic cao. Thường xuyên tiếp xúc với dầu, mỡ và các loại hóa chất độc hại để vệ sinh, bảo dưỡng, tiếp xúc với các loại sóng điện từ cao tần sử dụng trong thông tin liên lạc và tiếp xúc với các tia phóng xạ khi kiểm tra khuyết tật bằng từ tính CD1500, tư thế lao động gò bó, chật hẹp, có vị trí phải nằm, bò để sửa chữa.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9911, N'001033', N'Bộ đội phòng thủ đảo xa.', N'V', N'Công việc nguy hiểm, chịu tác động của thời tiết, sóng gió, ẩm ướt dễ nhiễm khuẩn, nhiễm bệnh.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9912, N'001034', N'Bộ đội Hải quân đánh bộ.', N'V', N'Vừa hoạt động dưới tàu biển, vừa bơi lội dưới nước và vận động trên bộ, công việc nặng nhọc, nguy hiểm.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9913, N'001035', N'Sửa chữa, lắp đặt máy tàu, thiết, bị vũ khí trong hầm tàu chiến.', N'V', N'Công việc nặng nhọc, độc hại, độ ồn lớn, nơi làm việc chật hẹp, tư thế làm việc gò bó.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9914, N'001036', N'Trực tiếp lắp ráp, kiểm tra, hiệu chỉnh, sửa chữa, bảo quản đạn ngư lôi, tên lửa, thuỷ lôi, bom phóng, bom chìm, đạn pháo tàu.', N'V', N'Công việc rất nguy hiểm, tiếp xúc với hoá chất độc, tư thế lao động gò bó, tập trung chú ý cao, căng thẳng thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9915, N'001037', N'Vận hành máy nén khí nạp vào tên lửa tàu Hải quân.', N'V', N'Công việc rất nguy hiểm, độc hại, ồn, nóng, độ bụi cao.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9916, N'001038', N'Gò, hàn, lắp ráp trong sửa chữa, đóng mới tàu quân sự.', N'V', N'Nơi làm việc chật hẹp ẩm ướt, bẩn và thiếu dưỡng khí, tư thế làm việc gò bó chịu tác động của khí CO, CO2, MnO2 và ồn.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9917, N'001039', N'Nấu, đúc, rèn, nhiệt luyện các chi tiết trong đóng mới, sửa chữa tàu quân sự.', N'V', N'Công việc rất nặng nhọc, rất nóng, ảnh hưởng của bức xạ nhiệt CO2, SO2.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9918, N'001040', N'Thử nghiệm, thử kín, lắp đặt, sửa chữa hệ thống điện, đường ống, ắc quy trong hầm tàu quân sự.', N'V', N'Nóng, ẩm ướt, tư thế làm việc gò bó, thường xuyên tiếp xúc với dầu mỡ, chất độc.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9919, N'001041', N'Sửa chữa, lắp đặt ra đa tàu quân sự.', N'V', N'Chịu ảnh hưởng của điện từ trường siêu cao tần. Tư thế làm việc gò bó.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9920, N'001042', N'Làm việc trên tàu ứng cứu, xử lý sự cố tràn dầu trên sông, biển.', N'V', N'Công việc khẩn cấp, nguy hiểm, tiếp xúc với khí độc.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9921, NULL, N'Xây dựng, lắp đặt, sửa chữa các công trình nài hải đảo.', N'V', N'Làm việc nài trời, lao động thủ công, nặng nhọc, nguy hiểm, chịu tác động của sóng, gió, ẩm ướt.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9922, N'001044', N'Sửa chữa, lắp ráp, hiệu chỉnh các thiết bị quang điện tử, hỏi đáp thông tin, đo lường hàng hải trên các tàu quân sự.', N'V', N'Nơi làm việc chật hẹp, nóng, thiếu dưỡng khí, ồn chịu ảnh hưởng của sóng điện từ, căng thẳng thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9923, N'001045', N'Sỹ quan, thuyền viên tàu cá vũ trang.', N'V', N'Công việc nặng nhọc, nguy hiểm, chịu tác động sóng, gió, rung lắc, ồn, căng thẳng thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9924, N'001046', N'Sửa chữa các hệ thống Sona trên tàu quân sự.', N'V', N'Nơi làm việc chật hẹp, nóng, thiếu dưỡng khí, chịu ảnh hưởng của sóng điện từ trường, sóng siêu âm, căng thẳng thần kinh.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9925, N'001047', N'Khai thác, vận hành, sửa chữa ra đa quan sát hải quân.', N'V', N'Chịu ảnh hưởng tiếng ồn, điện từ trường, bức xạ màn hình ra đa.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9926, N'001048', N'Lắp đặt, sửa chữa khí tài, thiết bị điện tử, thiết bị thông tin trong đóng mới, sửa chữa tàu quân sự.', N'V', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại, ẩm ướt, thường xuyên làm việc trong các khoang, hầm tàu chật hẹp, gò bó, sóng điện từ, sóng siêu cao tần, nóng bức, thiếu dưỡng khí.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9927, N'001049', N'Vận chuyển, bốc xếp thủ công vật tư, vũ khí, đạn dược, khí tài, trang thiết bị phục vụ đóng mới, sửa chữa tàu quân sự.', N'V', N'Người lao động làm việc không theo giờ cố định; công việc thủ công, làm việc nài trời, tiếp xúc với nắng, khói, bụi, tiếng ồn.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9928, NULL, N'Vận hành, bảo dưỡng các hệ thống, trang thiết bị đảm bảo năng lượng cho tàu ngầm.', N'V', N'Công việc nài trời, trên cao, dưới hầm ẩm ướt trong thời gian dài 24/24; căng thẳng thần kinh, tâm lý; tiếp xúc trực tiếp với các khí làm lạnh độc hại (R-22), tiếng ồn lớn và nguy hiểm (áp lực khí cao áp đến 400kgf/cm2, điện áp cao 380V). Tiếp xúc trực tiếp với dung dịch axít khi nạp luyện Ắc quy mới, dung dịch bẩn do nước thải công nghiệp, hóa chất xử lý nước thải, tư thế làm việc gò bó, đơn điệu, chủ yếu là đứng làm việc trong thời gian dài.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9929, NULL, N'Trực tiếp điều hành, khai thác, điều khiển, bảo dưỡng, sửa chữa rô bốt ngầm phục vụ cho cứu nạn tầu ngầm bị nạn.', N'V', N'Thường xuyên làm việc liên tục không theo khung giờ cố định, có cả thời gian ban đêm. Làm việc trong điều kiện tiếng ồn cao, rung lắc, chịu ảnh hưởng trực tiếp của bức xạ màn hình, sóng vô tuyến của hệ thống đài trạm. Không gian làm việc chật hẹp trong buồng điều khiển, tư thế ngồi lâu, cúi đầu.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9930, NULL, N'Vận hành đà đốc và đốc nổi vận chuyển tàu ngầm; vận hành, bảo dưỡng hệ thống phục vụ sửa chữa tàu ngầm.', N'V', N'Làm việc trong điều kiện vi khí hậu nóng, ẩm; tiếp xúc với tiếng ồn lớn; nồng độ bụi mịn, bụi sơn, bụi mạt sắt; thường xuyên tiếp xúc với dầu, mỡ và các loại hóa chất độc hại như axít, hóa chất để vệ sinh, sơn…, tư thế lao động gò bó, chật hẹp, có vị trí phải nằm, bò để sửa chữa.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9931, NULL, N'Kiểm tra, giám sát, hướng dẫn kỹ thuật, an toàn lao động, điều độ sản xuất và nghiệm thu sản phẩm trong sửa chữa tàu ngầm.', N'V', N'- Làm việc trong nhiều địa hình khác nhau từ trên boong tàu, phòng điều hành đến hầm máy tàu ngầm. Công việc đòi hỏi đi lại nhiều, trách nhiệm công việc cao dẫn đến căng thẳng thần kinh, tâm lý. Tiếp xúc với nhiều yếu tố tác hại nghề nghiệp khác nhau như vi khí hậu nóng, tiếng ồn, bụi, hơi khí độc, sóng điện từ trường...,tư thế làm việc, gò bó, chật hẹp.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9932, NULL, N'Làm việc trên xuồng tuần tra, kiểm soát vùng nước quân sự.', N'V', N'Làm việc nài trời nắng nóng, bức xạ nhiệt cao, trong môi trường chật hẹp, ấm ướt, trơn trượt, đi lại không đúng tư thế, rung xóc, tiếng ồn, tiếp xúc các loại dầu mỡ (diezel,…) trong điều kiện sóng gió phức tạp. Làm việc cả ngày và đêm với sự tập trung cao, luôn trong tình trạng căng thẳng tâm thần kinh do vừa điều khiển xuồng, vừa quan sát vùng nước, vừa phải xử lý các tình huống, xua đuổi mục tiêu.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9933, N'001055', N'Thợ cơ khí, vũ khí, sản xuất các chi tiết phụ tùng vũ khí dưới nước.', N'IV', N'Công việc nặng nhọc, chịu tác động của nóng, ồn, bụi.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9934, N'001056', N'Vệ sinh công nghiệp trong các nhà máy sửa chữa, đóng mới tàu, thuyền quân sự.', N'IV', N'Công việc thủ công, nặng nhọc, thường xuyên tiếp xúc với bụi, hoá chất.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9935, N'001057', N'Khai thác, sử dụng, sửa chữa các trang bị khí tài trên các tổ hợp tên lửa bờ.', N'IV', N'Công việc nặng nhọc, nơi làm việc chật hẹp, nóng, thiếu dưỡng khí, ồn, chịu ảnh hưởng của sóng siêu cao tần, căng thẳng thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9936, N'001058', N'Thủ kho, bảo quản, bốc xếp vật tư, trang bị khí tài trong kho khí tài điện tử.', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với dầu, mỡ, hoá chất độc hại.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9937, N'001059', N'Sơn xe ô tô quân sự bằng phương pháp thủ công và bằng máy phun sơn.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc hại, tư thế lao động gò bó.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9938, N'001060', N'Vận hành các phương tiện nâng, hạ, vận chuyển ở cảng quân sự.', N'IV', N'Làm việc trong điều kiện chật hẹp, tư thế lao động gò bó, nóng, nặng nhọc, ồn, rung, nguy hiểm, căng thẳng thần kinh.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9939, N'001061', N'Làm việc trong buồng giảm áp, máy nén khí cung cấp cho buồng giảm áp gắn trên trang thiết bị quân sự.', N'IV', N'Nơi làm việc chật hẹp, gò bó, nóng, áp suất cao, chịu tác động của tiếng ồn lớn, sóng gió, rung, lắc, căng thẳng thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9940, N'001062', N'Khảo sát, điều tra, đánh giá số liệu, điều vẽ, biên tập và in ấn hải đồ.', N'IV', N'Làm việc trong phòng kín, tiếp xúc với hoá chất độc hại, căng thẳng thị giác.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9941, N'001063', N'Giao nhận hàng hoá ở cảng quân sự.', N'IV', N'Công việc nài trời, ồn, bụi, căng thẳng thần kinh tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9942, N'001064', N'Tẩy, rửa làm sạch bề mặt vỏ tàu, sàn tàu, hầm tàu và các chi tiết máy móc trong đóng mới, sửa chữa tàu quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại, ẩm ướt, tư thế lao động gò bó, chịu tác động của hoá chất độc.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9943, N'001065', N'Gia công, lắp đặt, sửa chữa vỏ tàu, nội thất tàu trong đóng mới, sửa chữa tàu, xuồng quân sự (bằng vật liệu Composite, bông thuỷ tinh).', N'IV', N'Người lao động làm việc không theo giờ cố định. Môi trường làm việc gò bó, ồn, độc hại Axeton, nhựa, bụi thủy tinh.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9944, N'001066', N'Nghiên cứu, thí nghiệm, sản xuất sơn; kiểm tra chất lượng nguyên vật liệu và sản phẩm sơn; giám sát, kiểm tra quá trình bắn hạt và sơn tàu trong đóng mới, sửa chữa tàu quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại thường xuyên tiếp xúc với hơi dung môi, bụi sơn, bụi hóa chất vô cơ.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9945, N'001067', N'Vận hành, sửa chữa máy móc, thiết bị, phương tiện (xe tải, xe cẩu, xe nâng…) phục vụ đóng mới, sửa chữa tàu quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại thường xuyên ảnh hưởng rung lắc, tiếng ồn gây mệt mỏi, đau đầu, giảm thính lực, tư thế lao động gò bó, nóng bức. Tiếp xúc bụi silic, bụi hạt mài thép, bụi sơn.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9946, N'001068', N'Đốc công, giám sát an toàn trực tiếp, giám sát tại hiện trường trong đóng mới, sửa chữa tàu quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại thường xuyên làm việc tại hiện trường; nài trời, hầm tàu, nóng, bụi, ồn.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9947, N'001069', N'Vận hành, sửa chữa tàu kéo, tàu đẩy (lai dắt tàu) phục vụ đóng mới, sửa chữa tàu quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại thường xuyên chịu tác động của tiếng ồn, hơi nóng, sóng, gió.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9948, N'001070', N'Đánh giá NDT trong sửa chữa, đóng mới tàu quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định. Nơi làm việc chật hẹp, thiếu ánh sáng, công việc nguy hiểm tiếp xúc khí độc, tia bức xạ điện từ, hoá chất độc hại', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9949, N'001071', N'Sơ chế tôn trong thi công vỏ tàu quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, chịu ảnh hưởng bụi, tiếng ồn và các chất độc hại.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9950, NULL, N'Trực tiếp khai thác, vận hành hệ thống buồng áp trong y học quân sự.', N'IV', N'Công việc đặc thù, thường xuyên chịu tác động tiếng ồn, thay đổi áp suất; không gian gò bó trong buồng áp; công việc phức tạp, thường xuyên phải quan sát màn hình, mức độ trách nhiệm lớn trong cấp cứu điều trị cho nạn nhân dẫn đến căng thẳng thần kinh, tâm lý.', 11);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9951, N'001073', N'Kíp xe tăng, thiết giáp bánh xích.', N'VI', N'Công việc nặng nhọc, nơi làm việc nóng, chật hẹp, thiếu dưỡng khí, ánh sáng, ảnh hưởng khí CO2, ồn, rung và bụi vượt mức tiêu chuẩn cho phép nhiều lần.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9952, N'001074', N'Huấn luyện thực hành kíp xe tăng, thiết giáp bánh xích, bánh lốp.', N'VI', N'Công việc nặng nhọc, nguy hiểm, độc hại do tác động của khói thuốc súng và tiếng động lớn, nơi làm việc chật hẹp, nóng bức, tập trung cao độ, căng thẳng thần kinh tâm lý.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9953, N'001075', N'Bảo quản, bảo dưỡng, sửa chữa các thiết bị vũ khí, khí tài trên xe tăng, thiết giáp trong hang ngầm quân sự.', N'VI', N'Nơi làm việc chật hẹp, nóng, lạnh, thiếu dưỡng khí.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9954, N'001076', N'Kiểm tra, chạy thử xe tăng, thiết bị bánh lốp.', N'VI', N'Công việc nặng nhọc, nơi làm việc nóng, chật hẹp, thiếu dưỡng khí, rung và bụi vượt mức tiêu chuẩn cho phép.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9955, N'001077', N'Huấn luyện thực hành lái và bắn trên xe tăng, thiết giáp bánh xích.', N'VI', N'Công việc nặng nhọc, nguy hiểm, nơi làm việc nóng, chật hẹp, tập trung chú ý cao, căng thẳng thần kinh tâm lý.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9956, N'001078', N'Kiểm tra, chạy thử xe tăng thiết giáp bánh xích.', N'V', N'Công việc nặng nhọc, nơi làm việc nóng, chật hẹp, ồn, rung, bụi, căng thẳng thần kinh tâm lý.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9957, N'001079', N'Lái các loại xe chở xe tăng; kíp xe thiết giáp bánh lốp.', N'V', N'Công việc nặng nhọc, tư thế làm việc gò bó, ồn, rung vượt tiêu chuẩn cho phép nhiều lần.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9958, N'001080', N'Tẩy rửa xe tăng qua bể xút; sửa chữa bánh tỳ, ép gíp mặt máy, thử lực máy nổ tăng, thiết giáp.', N'V', N'Công việc thủ công rất nặng nhọc, độc hại, ồn lớn.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9959, N'001081', N'Sửa chữa các thiết bị vũ khí, khí tài trên xe tăng, thiết giáp.', N'V', N'Nơi làm việc chật hẹp, gò bó, nóng, chịu tác động của tiếng ồn lớn.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9960, N'001082', N'Lái xe công trình phục vụ sửa chữa các thiết bị vũ khí, khí tài trên xe tăng, thiết giáp trong hang ngầm quân sự.', N'V', N'Công việc nặng nhọc, nguy hiểm, nơi làm việc chật hẹp, nóng, lạnh, thiếu dưỡng khí.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9961, N'001083', N'Bảo quản, bảo dưỡng các thiết bị điện trong hang ngầm quân sự.', N'V', N'Nơi làm việc chật hẹp, nóng, lạnh, thiếu dưỡng khí.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9962, N'001084', N'Hàn các chi tiết trong sửa chữa các thiết bị vũ khí, khí tài trang bị trên xe tăng, thiết giáp.', N'V', N'Nơi làm việc chật hẹp, gò bó, nóng, nguy hiểm, thường xuyên tiếp xúc với hơi khí độc.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9963, N'001085', N'Tẩy rửa các thiết bị vũ khí, khí tài trang bị trên xe tăng, thiết giáp và đạn bằng hoá chất theo phương pháp thủ công.', N'V', N'Nơi làm việc nóng, thường xuyên tiếp xúc với hoá chất độc hại như axít, xút, ête.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9964, N'001086', N'Vận hành máy nén khí nạp vào bình chứa khí nén cho xe tăng, thiết giáp.', N'V', N'Công việc nặng nhọc, nguy hiểm, chịu tác động của tiếng ồn cao.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9965, N'001087', N'Thợ gia công cơ khí chi tiết sửa chữa các thiết bị vũ khí, khí tài trang bị trên xe tăng, thiết giáp.', N'V', N'Nơi làm việc nóng chịu tác động của bụi kim loại, chịu tác động của ồn, rung.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9966, N'001088', N'Sơn xe tăng, xe thiết giáp bằng phương pháp thủ công và bằng máy phun sơn.', N'V', N'Tư thế lao động gò bó, thường xuyên tiếp xúc với hoá chất độc.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9967, N'001089', N'Lái xe cẩu phục vụ sửa chữa các thiết bị vũ khí, khí tài trang bị trên xe tăng, thiết giáp.', N'V', N'Làm việc nài trời, chật hẹp, nóng, căng thẳng thị giác, chịu tác động của tiếng ồn, bụi.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9968, N'001090', N'Sửa chữa các thiết bị, vũ khí, khí tài trên xe tăng, thiết giáp.', N'V', N'Nơi làm việc chật hẹp, tư thế lao động gò bó, tiếp xúc xăng, dầu mỡ.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9969, N'001091', N'Làm nhiệm vụ trên xe chiến đấu bộ binh cơ giới.', N'IV', N'Tư thế lao động gò bó, chật hẹp, thiếu dưỡng khí, chịu tác động ồn, rung vượt tiêu chuẩn cho phép.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9970, N'001092', N'Thủ kho, bảo quản, bốc xếp trang thiết bị khí tài trong kho trang bị khí tài xe tăng, thiết giáp.', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với dầu mỡ, hoá chất độc.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9971, N'001093', N'Giáo viên dạy thực hành sửa chữa tăng, thiết giáp.', N'IV', N'Tư thế làm việc gò bó, chật hẹp, nóng bức, thường xuyên tiếp xúc với xăng, dầu mỡ, tiếng ồn, căng thẳng thần kinh.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9972, N'001094', N'Sửa chữa các thiết bị tăng, thiết giáp trên xe công trình.', N'IV', N'Nơi làm việc chật hẹp, gò bó, chịu tác động của tiếng ồn lớn.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9973, N'001086', N'Vận hành máy nén khí nạp vào bình chứa khí nén cho xe tăng, thiết giáp.', N'IV', N'Công việc nặng nhọc, nguy hiểm, chịu tác động của tiếng ồn cao.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9974, N'001096', N'Bảo vệ hang ngầm quân sự ở vùng rừng núi.', N'IV', N'Làm việc nài trời, căng thẳng thần kinh.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9975, N'001097', N'Vận hành trạm nạp ắc quy xe tăng, thiết giáp.', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với hoá chất độc hại.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9976, N'001098', N'Thủ kho kim khí, hóa chất bảo quản, bảo dưỡng, sửa chữa vật tư kỹ thuật tên lửa, khí tài đặc chủng, đạn chống tăng.', N'IV', N'Làm việc không theo giờ cố định. Công việc rất nguy hiểm, dễ cháy nổ, tiếp xúc với hoá chất độc, ảnh hưởng tới hệ thần kinh, tiêu hoá, miễn dịch.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9977, N'001099', N'Kiểm định kỹ thuật xe tăng, thiết giáp.', N'IV', N'Làm việc không theo giờ cố định. Công việc gò bó, chật hẹp, thiếu ánh sáng, tiếp xúc dầu mỡ, khí độc, hoá chất độc hại, căng thẳng thần kinh tâm lý.', 13);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9978, N'001100', N'Sử dụng phương tiện ngầm, tàu ngầm đặc công.', N'VI', N'Công việc nặng nhọc, nguy hiểm, chịu áp suất cao thiếu dưỡng khí, căng thẳng thần kinh tâm lý.', 14);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9979, N'001101', N'Đặc công người nhái, đặc công nước.', N'VI', N'Công việc nặng nhọc, nguy hiểm, thiếu dưỡng khí, tiếp xúc vi sinh vật có hại.', 14);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9980, N'001102', N'Lực lượng đặc công chống khủng bố.', N'VI', N'Công việc căng thẳng thần kinh, rất nguy hiểm, phải tiếp xúc và sử dụng các loại vũ khí, trang bị đặc chủng (gồm cả các loại hóa chất độc).', 14);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9981, N'001103', N'Điệp báo hoạt động trong mục tiêu.', N'VI', N'Nhiệm vụ độc lập, nguy hiểm, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9982, N'001104', N'Quản lý người bị tạm giữ, tạm giam và phạm nhân tại các cơ sở giam giữ trong quân đội.', N'VI', N'Thường xuyên bám sát phạm nhân trong lao động cải tạo nài trời dưới điều kiện thời tiết khắc nhiệt; sẵn sàng nguy hiểm đến sức khỏe vì đối tượng phạm nhân chống đối, manh động; ở vùng sâu, vùng xa, căng thẳng thần kinh, tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9983, N'001105', N'Đặc công biệt động.', N'V', N'Công việc nặng nhọc, nguy hiểm, độc hại, căng thẳng thần kinh tâm lý.', 14);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9984, N'001106', N'Đặc công bộ.', N'V', N'Làm việc nài trời, nặng nhọc, nguy hiểm, độc hại, căng thẳng thần kinh tâm lý.', 14);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9985, N'001107', N'Đội mẫu đặc công.', N'V', N'Làm việc nài trời, công việc nặng nhọc, nguy hiểm, độc hại, căng thẳng thần kinh tâm lý.', 14);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9986, N'001108', N'Giáo viên chuyên nghiệp nghiên cứu và dạy võ đặc công.', N'V', N'Làm việc nài trời, công việc nặng nhọc, nguy hiểm, căng thẳng thần kinh tâm lý.', 14);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9987, N'001109', N'Giáo viên trinh sát biệt động, tình báo.', N'V', N'Trực tiếp tiếp xúc với môi trường độc hại, công việc nặng nhọc, nguy hiểm, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9988, NULL, N'Trinh sát đặc nhiệm, trinh sát nại tuyến.', N'V', N'Nhiệm vụ độc lập, nài trời công việc nặng nhọc, nguy hiểm.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9989, N'001111', N'Trinh sát kỹ thuật.', N'V', N'Làm công việc nài trời, công việc nặng nhọc, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9990, N'001112', N'Nghiên cứu, thử nghiệm, điều chế, sử dụng các loại hóa chất kỹ thuật tình báo.', N'V', N'Làm việc trong buồng kín, thiếu dưỡng khí, tiếp xúc hóa chất độc và bức xạ nguy hiểm.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9991, NULL, N'Điệp báo hoạt động nài mục tiêu.', N'V', N'Nhiệm vụ độc lập, chịu tác động nhiều thông tin phức tạp, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9992, N'001114', N'Trinh sát mạng và trinh sát vũ trụ.', N'V', N'Làm việc nài trời và trong phòng kín, tiếp nhận nhiều thông tin, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9993, N'001115', N'Tuần tra, canh gác vũ trang bảo vệ các mục tiêu trọng yếu.', N'V', N'Làm việc độc lập nài trời, trực tiếp giải quyết người, hàng hóa, phương tiện ra vào mục tiêu dưới thời tiết mưa gió, nắng, nóng bức mệt mỏi, căng thẳng thần kinh, tiêu hao sức khỏe lớn.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9994, N'001116', N'Trinh sát bộ đội.', N'V', N'Công việc nài trời nặng nhọc, trực tiếp, độc lập, đòi hỏi tinh thần tập trung, linh hoạt, thể lực khỏe mạnh, kỹ năng vận động các động tác linh hoạt; làm việc trong điều kiện áp lực, căng thẳng thần kinh, tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9995, N'001117', N'Nghiên cứu, thử nghiệm, chế tạo các loại máy kỹ thuật tình báo.', N'IV', N'Chịu tác động bức xạ màn hình và điện từ trường cao tần, căng thẳng thị giác.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9996, N'001118', N'Nghiên cứu, sản xuất các loại giấy đặc biệt; in các loại tài liệu mật mã.', N'IV', N'Làm việc trong buồng kín, tiếp xúc với hóa chất độc hại.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9997, N'001119', N'Sử dụng khí tài quang học tình báo.', N'IV', N'Tiếp xúc hóa chất độc hại, căng thẳng thần kinh thị giác.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9998, N'001120', N'Kỹ thuật nghe nhìn điệp báo.', N'IV', N'Làm việc trong buồng tối, kín, nóng, tiếp xúc chất độc hại, bức xạ sóng điện từ, căng thẳng thị giác.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (9999, N'001121', N'Mã thám.', N'IV', N'Làm việc trong buồng kín, thiếu dưỡng khí, chịu tác động bức xạ điện từ trường, màn hình.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10000, N'001122', N'Nghiên cứu, tổng hơp, phân tích đánh giá chiến lược các đối tượng địch.', N'IV', N'Giải quyết nhiều công việc phức tạp căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10001, N'001123', N'Điệp báo hoạt động địa bàn Biên giới và Hải đảo.', N'IV', N'Nhiệm vụ độc lập, nguy hiểm, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10002, N'001124', N'Giáo viên điệp báo, kỹ thuật điệp báo.', N'IV', N'Làm việc trong buồng kín, thiếu dưỡng khí, tiếp xúc với hoá chất; huấn luyện nài trời, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10003, N'001125', N'Nghiên cứu, ứng dụng công nghệ hoá và vật liệu điệp báo.', N'IV', N'Tiếp xúc với hoá chất độc hại, nguy hiểm.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10004, N'001126', N'Nghiên cứu, ứng dụng kỹ thuật tin học tình báo và tình báo khoa học công nghệ.', N'IV', N'Chịu tác động bức xạ màn hình và điện từ trường cao tần, căng thẳng thị giác.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10005, N'001127', N'Nghiên cứu, khai thác, bảo quản kho tư liệu, tài liệu tình báo. Nhân viên thư viện quản lý tài liệu nghiệp vụ tình báo.', N'IV', N'Làm việc trong buồng kín, thiếu dưỡng khí, tiếp xúc với hoá chất độc hại, căng thẳng thần kinh tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10006, N'001128', N'Nhân viên xưởng in tài liệu giáo trình tình báo.', N'IV', N'Thường xuyên làm việc trong phòng kín; tư thế lao động gò bó; tiếp xúc với hơi, bụi độc; căng thẳng thần kinh; tính bảo mật cao.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10007, N'001129', N'Điều tra án hình sự.', N'IV', N'Công việc nguy hiểm, thường xuyên lưu động (xác minh lời khai, thu thập chứng cứ), căng thẳng thần kinh, tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10008, NULL, N'Lực lượng kiểm soát quân sự chuyên nghiệp.', N'IV', N'Nhiệm vụ phức tạp, tính chất nhiệm vụ trọng yếu; địa điểm và mục tiêu bảo vệ luôn vận động, không cố định; các nhiệm vụ đều thực hiện nài doanh trại, tiếp xúc nhiều đối tượng, có nguy cơ cao đến an toàn tính mạng bản thân và VKTB khi thực hiện nhiệm vụ; làm việc trong điều kiện áp lực, căng thẳng thần kinh, tâm lý, thường xuyên tiếp xúc trực tiếp với điều kiện thời tiết như nóng, lạnh, mưa, bụi, căng thẳng thị giác và chịu tác động của ồn, rung.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10009, NULL, N'Lái xe trinh sát; lái xe chở bộ đội tuần tra, canh gác vũ trang.', N'IV', N'Làm việc trong điều kiện áp lực, căng thẳng thần kinh, tâm lý, tư thế gò bó, môi trường làm việc nặng nhọc, tiếp xúc trực tiếp với xăng, dầu độc hại. Công việc nài trời nặng nhọc, tiếp xúc trực tiếp với điều kiện thời tiết như nóng lạnh, mưa, bụi, căng thẳng thị giác và chịu tác động của ồn, rung.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10010, N'001132', N'Giám định kỹ thuật hình sự.', N'', N'Làm việc trong phòng kín, kém thông thoáng, chịu ảnh hưởng chất độc, khí độc, căng thẳng thần kinh, tâm lý.', 15);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10011, N'001133', N'Điều khiển pháo mặt đất tự hành.', N'VI', N'Công việc rất nặng nhọc, môi trường lao động nóng, chật hẹp, gò bó, thiếu dưỡng khí, thiếu ánh sáng, ảnh hưởng khí CO2, ồn, rung, bụi vượt tiêu chuẩn cho phép.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10012, N'001134', N'Điều khiển ra đa mặt đất.', N'VI', N'Công việc nặng nhọc, nơi làm việc nóng, chật hẹp, gò bó, thiếu dưỡng khí, ánh sáng ồn, rung, bụi vượt tiêu chuẩn cho phép.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10013, N'001135', N'Sử dụng pháo mang vác.', N'V', N'Công việc nặng nhọc, nguy hiểm, ảnh hưởng đến thính giác, thị giác.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10014, N'001136', N'Kíp sử dụng pháo phản lực, pháo tự hành, pháo xe kéo.', N'V', N'Công việc nặng nhọc, nguy hiểm, ồn, rung, căng thẳng thị giác.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10015, N'001137', N'Chỉ huy đại đội phóng tên lửa, trung đội chỉ huy, đội phóng (gồm kíp bệ phóng, kíp điều khiển) làm nhiệm vụ điều khiển tên lửa mặt đất.', N'V', N'Công việc nặng nhọc, rất nguy hiểm, thần kinh căng thẳng, ảnh hưởng tiếng ồn, rung xóc, bụi và nồng độ hóa chất độc hại cao.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10016, N'001138', N'Làm việc (theo kíp) trong xe huấn luyện tên lửa mặt đất.', N'V', N'Làm việc trong xe đặc chủng rất nóng, chật hẹp, gò bó, thiếu dưỡng khí, thiếu ánh sáng, ảnh hưởng của sóng điện từ.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10017, N'001139', N'Khai thác sử dụng các phương tiện thông tin liên lạc trong xe chỉ huy phóng tên lửa.', N'V', N'Làm việc trong xe kín, nóng, thiếu dưỡng khí, ảnh hưởng điện từ trường cao tần, căng thẳng thần kinh, thị giác.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10018, N'001140', N'Sử dụng khí tài pháo binh.', N'IV', N'Căng thẳng thần kinh thị giác, ảnh hưởng bức xạ điện từ trường.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10019, N'001141', N'Bắn kẹp nòng và bắn sa bàn pháo binh.', N'IV', N'Ảnh hưởng khói thuốc súng, căng thẳng thính giác, thị giác).', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10020, N'001142', N'Sử dụng tên lửa mặt đất vác vai.', N'IV', N'Công việc nặng nhọc, độc hại, nguy hiểm.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10021, N'001143', N'Sử dụng khí tài đo xa Laze và quang điện tử.', N'IV', N'Công việc cơ động, nguy hiểm, thường xuyên chịu ảnh hưởng của điện từ trường.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10022, N'001144', N'Thợ khắc thước Pháo binh.', N'IV', N'Thường xuyên tiếp xúc với bụi polyme, xăng, dầu, căng thẳng thần kinh.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10023, N'001145', N'Thợ sửa chữa, bảo dưỡng trạm nguồn điện tên lửa.', N'IV', N'Thường xuyên tiếp xúc với xăng dầu hoá chất, mệt mỏi thần kinh.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10024, N'001146', N'Thợ cơ khí tại các trạm, xưởng sửa chữa vũ khí.', N'IV', N'Căng thẳng thị giác, mệt mỏi thần kinh.', 12);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10025, N'001147', N'Trực tiếp rải mìn, rà phá bom, mìn, xử lý bom, mìn sau rà phá.', N'VI', N'Rất nguy hiểm, độc hại, căng thẳng thần kinh tâm lý.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10026, N'001148', N'Khoan đá, nổ mìn trong công trình ngầm quốc phòng.', N'VI', N'Làm việc dưới hầm, nặng nhọc, nguy hiểm, thiếu dưỡng khí, ánh sáng, nồng độ bụi lớn, căng thẳng thần kinh tâm lý.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10027, N'001149', N'Xây dựng công trình ngầm quốc phòng.', N'V', N'Làm việc trong hầm, nặng nhọc, nguy hiểm, thiếu dưỡng khí, ánh sáng, nồng độ bụi lớn.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10028, N'001150', N'Khảo sát đo đạc, xây dựng công sự trận địa, công trình quốc phòng, cầu bến, nửa lâu bền vùng rừng sâu, núi cao, hải đảo.', N'V', N'Địa hình làm việc phức tạp, công việc thủ công, nặng nhọc, nguy hiểm.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10029, N'001151', N'Kíp xe đặc chủng công binh bánh xích.', N'V', N'Công việc nặng nhọc, nơi làm việc chật hẹp, nóng, ồn, rung vượt tiêu chuẩn cho phép nhiều lần.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10030, N'001152', N'Bắc cầu quân sự vượt sông suối.', N'V', N'Làm việc nài trời, dưới nước, công việc thủ công, nặng nhọc, nguy hiểm.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10031, N'001153', N'Sản xuất ván ép nhân tạo phục vụ việc xây dựng lô cốt, công sự quân sự.', N'V', N'Tiếp xúc với hoá chất độc hại Phenol, Formaldehyd, axeton, xút, làm việc trong môi trường nóng, bụi, ồn.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10032, N'001154', N'Sản xuất khí tài công binh vượt sông phục vụ chiến đấu (bằng vật liệu CompoZít).', N'V', N'Tiếp xúc với hoá chất độc hại Axeton, nhựa, bụi thuỷ tinh.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10033, N'001155', N'Phun cát, mài làm sạch sản phẩm vũ khí, trang bị, xe máy công binh.', N'V', N'Công việc rất nặng nhọc, làm việc trong môi trường ồn, rung, bụi.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10034, N'001156', N'Sửa chữa, bảo dưỡng, bảo quản trong khoang thuyền PMP, TPP.', N'V', N'Thường xuyên làm việc trong khoang kín thiếu ánh sáng, tư thế làm việc gò bó, bụi, ồn.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10035, N'001157', N'Kíp xe đặc chủng công binh bánh lốp, xe công trình xa; sử dụng thiết bị đặc chủng công binh.', N'IV', N'Công việc nặng nhọc, nguy hiểm, rung xóc, ồn.', 10);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10036, N'001158', N'Nghiên cứu, chế thử, sản xuất chất độc quân sự.', N'VI', N'Tiếp xúc chất độc mạnh, nguy hiểm, nóng, thiếu dưỡng khí.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10037, N'001159', N'Nghiên cứu, chế thử, tinh chế làm giầu chất phóng xạ.', N'VI', N'Nguy hiểm, tiếp xúc chất phóng xạ, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10038, N'001160', N'Xử lý môi trường bị ô nhiễm chất độc, chất phóng xạ; xử lý, hủy chất độc, chất phóng xạ.', N'VI', N'Công việc nặng nhọc độc hại, nguy hiểm, tiếp xúc chất phóng xạ, chất độc.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10039, N'001161', N'Sử dụng vũ khi sinh học, hóa học, phương tiện có nguồn phòng xạ.', N'VI', N'Nguy hiểm, tiếp xúc chất độc, chất phóng xạ mạnh.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10040, N'001162', N'Nghiên cứu, phòng chống vũ khí huỷ diệt hàng loạt (hoá học, sinh học, hạt nhân) nghiên cứu sản xuất các trang bị khí tài hoá học.', N'VI', N'Tiếp xúc với hoá chất độc hại, nguy hiểm chất phóng xạ mạnh, tác nhân sinh học.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10041, N'001163', N'Thủ kho, thống kê, bảo quản, bốc xếp chất độc, chất phóng xạ quân sự tồn lưu sau chiến tranh.', N'VI', N'Tiếp xúc trực tiếp với chất độc, nguồn phóng xạ mạnh, căng thẳng thần kinh tâm lý, rất nguy hiểm.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10042, N'001164', N'Hiệu chuẩn, giữ chuẩn chính về đại lượng đo lường bức xạ. Nghiên cứu, sản xuất, bảo quản, sửa chữa khí tài trinh sát phóng xạ hóa học.', N'VI', N'Tiếp xúc với chất phóng xạ, chất độc, tác nhân sinh học rất nguy hiểm, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10043, N'001165', N'Nghiên cứu, chế thử, sản xuất, KCS chất tạo khói và khí tài phát khói, vũ khí lửa.', N'VI', N'Tiếp xúc với hoá chất độc, rất nguy hiểm, dễ cháy nổ.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10044, N'001166', N'Nghiên cứu công nghệ xử lý chất độc; nghiên cứu, chế thử, sản xuất, KCS, bảo quản, niêm cất các chất tiêu độc, tẩy xạ, diệt trùng.', N'VI', N'Trực tiếp sử dụng các hoá chất độc, rất nguy hiểm trong phòng thí nghiệm và khu nhiễm độc.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10045, NULL, N'Điều tra lấy mẫu, khai quật thu m, phân tích, phân loại chất độc, chất phóng xạ, tác nhân sinh học.', N'VI', N'Trực tiếp tiếp xúc với các hoá chất độc, rất nguy hiểm.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10046, N'001168', N'Tiêu độc, tẩy xạ, diệt trùng.', N'VI', N'Thường xuyên làm việc nài trời, công việc thủ công, rất nặng nhọc, trực tiếp tiếp xúc với vi sinh vật, hoá chất độc hại, nguy hiểm.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10047, N'001169', N'Xử lý sự cố môi trường do rò rỉ hoá chất độc, chất phóng xạ.', N'VI', N'Tiếp xúc với chất độc, chất phóng xạ, rất nguy hiểm.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10048, N'001170', N'Thanh, xử lý bom, đạn đặc chủng, hoá chất, vật tư độc hại.', N'VI', N'Tiếp xúc hoá chất độc hại, rất nguy hiểm, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10049, N'001171', N'Sản xuất, KCS các trang bị chống khủng bố.', N'VI', N'Tiếp xúc với hoá chất độc hại, rất nguy hiểm.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10050, N'001172', N'Thủ kho, bảo quản, bốc xếp chất độc, chất phóng xạ quân sự.', N'V', N'Nguy hiểm, tiếp xúc trực tiếp chất độc, chất phóng xạ mạnh, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10051, N'001173', N'Sử dụng khí tài phòng da, phòng hô hấp.', N'V', N'Nóng, thiếu dưỡng khí, tiêu hao năng lượng lớn.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10052, N'001174', N'Nghiên cứu, sản xuất, sửa chữa phương tiện có nguồn phóng xạ, phương tiện mang chất phóng xạ, phương tiện đo phóng xạ.', N'V', N'Tiếp xúc chất phóng xạ, nguy hiểm, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10053, N'001175', N'Sản xuất chất tạo khói, vũ khí lửa.', N'V', N'Tiếp xúc chất độc hại, nguy hiểm, dễ cháy nổ.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10054, N'001176', N'Lái, phụ xe, áp tải xe chở chất độc, chất phóng xạ quân sự.', N'V', N'Rất nguy hiểm, tiếp xúc ồn, rung, xóc, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10055, N'001177', N'Sửa chữa xe đặc chủng hoá học quân sự.', N'V', N'Trực tiếp tiếp xúc với chất độc, nguồn phóng xạ, tư thế làm việc gò bó, nơi làm việc chật hẹp, nóng, chịu tác động của tiếng ồn trong khoang kín.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10056, N'001178', N'KCS, sửa chữa, sản xuất khí tài hoá học quân sự.', N'V', N'Tiếp xúc hoá chất độc hại, tư thế làm việc gò bó, nơi làm việc chật hẹp, nóng, ồn.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10057, N'001179', N'Thủ kho, thống kê, bảo quản, niêm cất, vận hành xe đặc chủng trong kho; bốc xếp bảo dưỡng phụ tùng khí tài hoá học quân sự.', N'V', N'Tiếp xúc với hoá chất độc, nguồn phóng xạ, nóng, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10058, N'001180', N'Sản xuất mặt nạ, xử lý mắt kính, phin lọc độc, KCS hộp lọc độc quân sự.', N'V', N'Tiếp xúc với hoá chất độc hại, nhiệt độ cao, tiếng ồn, bụi a mi ăng, căng thẳng thần kinh, ảnh hưởng thị lực, tư thế gò bó.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10059, N'001181', N'KCS, sản xuất than hoạt tẩm chất xúc tác, ống trinh độc quân sự.', N'V', N'Tiếp xúc với hoá chất độc hại, bụi thuỷ tinh và chất độc mô phỏng (MOB).', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10060, N'001182', N'Thủ kho, thống kê, bảo quản khí tài trinh sát hoá học, phóng xạ, khí tài phòng hô hấp, phòng da, quan sát hoá học quân sự.', N'V', N'Công việc nặng nhọc, nơi làm việc chật hẹp, tiếp xúc hoá chất độc, nguồn phóng xạ, rất nguy hiểm.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10061, N'001183', N'Thủ kho, thống kê, bảo quản, bốc xếp hoá chất huấn luyện, hoá chất tiêu tẩy, chất cháy quân sự.', N'V', N'Công việc nặng nhọc, tiếp xúc với hoá chất độc hại, rất nguy hiểm, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10062, NULL, N'Giảng viên giảng dạy các nội dung kỹ, chiến thuật chuyên ngành Phòng hóa.', N'V', N'Làm việc trong môi trường độc hại do hóa chất độc và chất phóng xạ, ảnh hưởng đến sức khỏe cả ngắn hạn và dài hạn: Huấn luyện các bài giảng lý thuyết, thực hành tại phòng thí nghiệm và thao trường, bãi tập, diễn tập, trong quá trình làm việc luôn luôn sử dụng mặt nạ phòng độc và chất độc thật để thực hành, huấn luyện', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10063, N'001185', N'Giảng viên, kỹ thuật viên giảng dạy các nội dung hóa học.', N'V', N'Làm việc trong phòng thí nghiệm (Phòng kín), tiếp xúc với hóa chất độc hại, ảnh hưởng đến sức khỏe cả ngắn hạn và dài hạn', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10064, N'001186', N'Thử nghiệm độ bền nhiệt đới, vật liệu, trang thiết bị đặc chủng quân sự.', N'V', N'Thường xuyên làm việc không theo khung giờ cố định khi có nhiệm vụ đặc biệt, thường xuyên tiếp xúc với nóng bức, tiếng ồn, hóa chất độc và chất phóng xạ, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10065, N'001187', N'Nghiên cứu, chế thử các mô-đun, thiết bị điện-điện tử, vật liệu đảm bảo kỹ thuật cho các trang thiết bị đặc chủng.', N'V', N'Thường xuyên làm việc không theo khung giờ cố định khi có nhiệm vụ đặc biệt, thường xuyên tiếp xúc với hóa chất độc và chất phóng xạ, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10066, NULL, N'Nghiên cứu công nghệ, vận hành trang thiết bị nhiệt luyện, hóa - nhiệt luyện, mạ điện và phun phủ kim loại.', N'V', N'Thường xuyên tiếp xúc với nhiệt độ và tiếng ồn và cường độ ánh sáng cao từ các trang bị mài, cắt, nhiệt luyện và hóa - nhiệt luyện và phun phủ kim loại; bụi kim loại trong quá trình cắt, mài, phun cát đánh gỉ và phun phủ kim loại, nguy cơ phơi nhiễm với bụi kim loại cao đặc biệt là bụi silic; hơi khí độc như: Hơi dầu tôi, dung môi dễ bay hơi. Cường độ lao động cao, tiềm ẩn nhiều yếu tố gây tai nạn lao động như cháy nổ, điện giật, cưa cắt…, tính chất công việc căng thẳng kéo dài dễ gây mệt mỏi, ảnh hưởng sức khỏe.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10067, N'001189', N'Khảo sát, điều tra, thu thập, vận chuyển, xử lý, làm tiêu bản các mẫu sinh học (thực vật, động vật, nấm, vi sinh vật, cổ sinh vật).', N'V', N'Thường xuyên làm việc không theo khung giờ cố định khi có nhiệm vụ đặc biệt, tiếp xúc với hóa chất độc, vi khuẩn, nấm, vi rút, động, thực vật nguy hại, nơi làm việc chật hẹp, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10068, NULL, N'Thu thập, kiểm kê, bảo quản, xử lý kỹ thuật các mẫu vật (sinh học, địa chất, vật liệu) trong phòng lưu trữ, trưng bày mẫu vật của đơn vị.', N'V', N'Công việc thu thập mẫu rất phức tạp, cường độ lao động cao, diễn ra trong thời gian dài, không kể ngày đêm gây ảnh hưởng đến sức khỏe và thần kinh tâm lý. Thường xuyên tiếp xúc trực tiếp các hóa chất độc hại để xử lý, bảo quản mẫu. Công việc kiểm kê, bảo quản mẫu vật trong phòng lưu trữ, làm việc trong phòng kín, nhiều hóa chất độc hại, thiếu dưỡng khí.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10069, NULL, N'Thử nghiệm, sinh sản nhân tạo; chăm sóc, nuôi dưỡng, bảo tồn các loài thủy sinh vật.', N'V', N'Công việc nặng nhọc, làm việc nài trời, trong đầm, sông, hồ, thường xuyên tiếp xúc với hóa chất, kích dục tố,... Tiếp xúc thường xuyên với nước, chất thải, vi sinh vật gây bệnh, dễ mắc bệnh da liễu và hô hấp. Phần lớn thời gian làm việc nài trời, thời tiết nóng, ẩm và tiếp xúc với trực tiếp với bức xạ mặt trời để theo dõi các chỉ số môi trường và sức khỏe, sinh sản của vật nuôi. Làm việc trên các bè nuôi thủy sinh vật trong điều kiện sóng gió dễ trơn trượt, tiềm ẩn nguy cơ tai nạn, bị trầy xước, đâm, cắn khi thao tác với cá bố mẹ hoặc thủy sản có gai, vỏ cứng.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10070, N'001192', N'Nghiên cứu, chế thử các loại khí tài phòng độc; phân tích, hoá nghiệm, hoá sinh; đánh giá tác động môi trường tại những khu vực bị ô nhiễm và nghiên cứu các tác nhân hoá học, sinh học.', N'V', N'Thường xuyên làm việc trong các phòng thí nghiệm, tiếp xúc trực tiếp với các loại hoá chất độc hại, nguy hiểm; tiếp xúc với khí hậu, thời tiết khắc nghiệt và môi trường độc hại, căng thẳng thần kinh, tâm lý và tiêu hao năng lượng.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10071, N'001193', N'Sản xuất ống trinh độc, phương tiện dụng cụ trinh sát hóa học, chất và dụng cụ tiêu tẩy.', N'IV', N'Chịu tác động của hóa chất độc hại.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10072, N'001194', N'Sản xuất than hoạt tẩm xúc tác.', N'IV', N'Công việc nặng nhọc, nóng, tiếp xúc bụi than và khí CO2.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10073, N'001195', N'Thủ kho, bảo quản khí tài trinh sát hóa học, phóng xạ, khí tài phòng hô hấp, phòng da, quan sát hóa học.', N'IV', N'Nơi làm việc chật hẹp, tiếp xúc hóa chất độc.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10074, N'001196', N'Thủ kho, bảo quản, bốc xếp hóa chất độc hại, hóa chất tiêu tẩy, chất cháy quân sự.', N'IV', N'Tiếp xúc hóa chất độc hại, nguy hiểm, căng thẳng thần kinh tâm lý.', 4);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10075, N'001197', N'Lắp đặt, sửa chữa bảo dưỡng các thiết bị thông tin quân sự (trên cột anten cao từ 30 m trở lên ở rừng núi).', N'VI', N'Công việc nặng nhọc, làm việc trên cao rất nguy hiểm, khi sửa chữa, bảo dưỡng chịu tác động của điện từ trường cao tần và siêu cao tần.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10076, N'001198', N'Vận hành, khai thác máy phát sóng siêu cao tần quân sự.', N'VI', N'Thường xuyên tiếp xúc với điện từ trường siêu cao tần, ảnh hưởng rất lớn tới sức khoẻ.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10077, N'001199', N'Vận hành, sửa chữa bảo dưỡng thiết bị trong xe thông tin quân sự.', N'V', N'Làm việc trong xe kín, nóng, thiếu dưỡng khí, ảnh hưởng điện từ trường cao tần, căng thẳng thần kinh, thị giác.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10078, N'001200', N'Vận hành sửa chữa, bảo dưỡng trạm phát vô tuyến điện quân sự cấp chiến lược.', N'V', N'Ảnh hưởng điện từ trường cao tần, căng thẳng thần kinh tâm lý.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10079, N'001201', N'Làm việc trực tiếp tại tổng đài thông tin liên lạc quân sự trong hầm sâu.', N'V', N'Nơi làm việc chật hẹp, thiếu ánh sáng, dưỡng khí, thường xuyên chịu tác động của điện từ trường.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10080, N'001202', N'Báo vụ vô tuyến điện báo quân sự.', N'V', N'ảnh hưởng của điện từ trường; căng thẳng về tâm lý, thần kinh; thường xuyên tiếp xúc với tiếng ồn, làm việc trong phòng kín, xe bịt kín, nhiệt độ cao; ảnh hưởng thị lực, thính lực.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10081, N'001203', N'Vận hành, bảo dưỡng, sửa chữa thiết bị thông tin vệ tinh, vi ba, vi sát ở các trạm thông tin quân sự trên núi cao, rừng sâu.', N'V', N'Làm việc ở vùng xa xôi, hẻo lánh; thường xuyên tiếp xúc với điện từ trường siêu cao tần vượt tiêu chuẩn cho phép.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10082, N'001204', N'Tuần tra, bảo vệ hệ thống cáp quang quân sự Bắc - Nam.', N'V', N'Thường xuyên lưu động trên các địa hình đồi núi, nguy hiểm, tiếp xúc với điện từ trường.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10083, N'001205', N'Vận hành, bảo quản, sửa chữa hệ thống cáp quang quân sự Bắc-Nam.', N'V', N'Thường xuyên lưu động trên các địa hình đồi núi, nguy hiểm, tiếp xúc với điện từ trường.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10084, N'001206', N'Vận hành, khai thác, sửa chữa, bảo dưỡng tổng đài quân sự có dung lượng từ 10.000 số trở lên, các đài trạm thông tin vệ tinh mặt đất.', N'V', N'Công việc đơn điệu, phải bảo đảm bí mật quân sự cao, thường xuyên chịu tác động của điện từ trường.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10085, N'001207', N'Vận hành, sửa chữa, bảo dưỡng trang thiết bị trong xe máy mã quân sự và trang bị kỹ thuật nghiệp vụ mật mã quân sự.', N'V', N'Làm việc trong điều kiện kín, chật hẹp, thiếu dưỡng khí, ảnh hưởng tiếng ồn lớn, khí độc của các loại vật liệu.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10086, N'001208', N'Trực tiếp bảo đảm thông tin liên lạc phục vụ đơn vị xe tăng huấn luyện chiến thuật.', N'V', N'Làm việc nài trời, nặng nhọc, ảnh hưởng điện từ trường, căng thẳng thần kinh tâm lý.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10087, N'001209', N'Chế thử, thử nghiệm, sản xuất mạch in máy thông tin quân sự.', N'V', N'Thường xuyên làm việc trong môi trường hoá chất độc hại, thiếu ánh sáng, thiếu dưỡng khí, tư thế gò bó, căng thẳng thần kinh.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10088, N'001210', N'Thi công, bảo dưỡng, sửa chữa đường dây trần thông tin ở vùng sâu, vùng rừng núi hiểm trở.', N'IV', N'Công việc nặng nhọc, thường xuyên làm việc trên cao, đồi núi, đầm lầy, hẻo lánh, nguy hiểm.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10089, N'001211', N'Quân bưu chuyển công văn mật, khẩn, hẹn giờ ở vùng trung du, rừng núi (trên 20km).', N'IV', N'Làm việc nài trời, đi trong mọi điều kiện, phương tiện tính khẩn trương cao.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10090, N'001212', N'Lắp đặt, bảo dưỡng, sửa chữa thiết bị truyền dẫn trên tuyến và mạng điện thoại quân sự.', N'IV', N'Làm việc nài trời, công việc nặng nhọc, nguy hiểm, tư thế lao động gò bó.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10091, N'001213', N'Vận hành, bảo dưỡng, sửa chữa máy thu, phát công suất từ 01 KW trở lên phục vụ thông tin liên lạc quân sự.', N'IV', N'Thường xuyên chịu tác động của điện từ trường.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10092, N'001214', N'Khai thác, sử dụng trạm thông tin vô tuyến điện tiếp sức quân sự.', N'IV', N'Thường xuyên tiếp xúc với bức xạ, sóng cao tần, nơi làm việc chật hẹp, tiếng ồn lớn, thiếu dưỡng khí.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10093, N'001215', N'Thủ kho, bảo quản, bốc xếp khí tài thông tin.', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với chất độc hại.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10094, N'001216', N'Xây lắp, sửa chữa, bảo dưỡng cáp ngầm thông tin quân sự.', N'IV', N'Làm việc thủ công, nặng nhọc, trong điều kiện mưa, nắng và bụi; khi sửa chữa, bảo dưỡng chịu tác động của mùi hôi thối.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10095, N'001217', N'Lực lượng vận hành công văn quân sự mật, tối khẩn, hẹn giờ.', N'IV', N'Công việc không kể ngày, đêm, thường xuyên đi lại trên đường, nguy hiểm, chịu ảnh hưởng của khí hậu, mưa, nắng, đòi hỏi tính khẩn trương, cơ mật cao.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10096, N'001218', N'Sửa chữa thiết bị đầu cuối điện thoại quân sự.', N'IV', N'Nơi làm việc chật hẹp, tư thế lao động gò bó, thường xuyên tiếp xúc với hoá chất.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10097, N'001219', N'Khảo sát đo đạc lắp đặt các công trình thông tin quân sự.', N'IV', N'Công việc nặng nhọc, tư thế lao động gò bó, chịu tác động của điện từ trường.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10098, N'001220', N'Bảo vệ vận chuyển công văn tài liệu quân sự, trên phương tiện tàu hoả tuyến Bắc - Nam.', N'IV', N'Công việc nặng nhọc, không kể ngày, đêm, chịu tác động của bụi, rung, xóc.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10099, N'001221', N'Khai thác điện thoại, điện toán, truyền số liệu, quản lý danh bạ điện thoại, xử lý phần mềm, lập trình và khai thác điện thoại quân sự.', N'IV', N'Thường xuyên tiếp xúc với màn hình, căng thẳng thần kinh tâm lý.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10100, N'001222', N'Sản xuất ống nhựa và các loại dây, cáp thông tin quân sự bọc nhựa.', N'IV', N'Thường xuyên tiếp xúc với nóng, hơi khí và bụi độc.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10101, N'001223', N'Chuốt dây kim loại.', N'IV', N'Tiếp xúc với bụi kim loại, hơi độc của dung môi hoá học.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10102, N'001224', N'Nhồi dầu cáp thông tin.', N'IV', N'Tiếp xúc với dầu, mỡ, hoá chất.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10103, N'001225', N'Khai thác công văn quân sự tối mật, hẹn giờ.', N'IV', N'Làm việc trong phòng kín, căng thẳng thần kinh.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10104, N'001226', N'Sửa chữa, kiểm tra chất lượng các loại máy thông tin quân sự.', N'IV', N'Thường xuyên tiếp xúc với hoá chất, chịu tác động của điện từ trường.', 47);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10105, N'001227', N'Chế tạo các loại thuốc nổ (nhạy nổ) và các sản phẩm trung gian.', N'VI', N'Rất nguy hiểm (dễ cháy nổ), thường xuyên tiếp xúc với hóa chất độc mạnh (hơi a xít đặc, các ô xít ni tơ, thủy ngân...), căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10106, N'001228', N'Chế tạo thuốc đen và những sản phẩm, bộ phận, chi tiết đạn dược có dùng thuốc đen.', N'VI', N'Rất nguy hiểm (dễ cháy nổ), ảnh hưởng bụi thuốc và hóa chất độc hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10107, N'001229', N'Chế tạo, tái sinh, đúc ép, nhồi thuốc nổ mạnh vào các loại đạn, bom, mìn.', N'VI', N'Rất nguy hiểm (dễ cháy nổ), thường xuyên chịu ảnh hưởng của hóa chất độc hại, tập trung chú ý cao, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10108, N'001230', N'Điều chế thuốc phóng.', N'VI', N'Rất nguy hiểm (dễ cháy nổ), thường xuyên tiếp xúc với bụi, hóa chất độc, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10109, N'001231', N'Thí nghiệm, chế thử, thử nghiệm, kiểm tra chất lượng, xử lý và sửa chữa đạn dược, nhiên liệu nòng tên lửa.', N'VI', N'Nguy hiểm, tiếp xúc hóa chất độc hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10110, N'001232', N'Quản lý, xử lý tiêu huỷ các loại đạn dược cấp 5 (bom, mìn, tên lửa, thuỷ lôi, đạn, hoả cụ...).', N'VI', N'Công việc rất nguy hiểm, độc hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10111, N'001233', N'Phân tích, kiểm tra đánh giá chất lượng, thành phần tính năng kỹ thuật của thuốc phóng, thuốc nổ, nhiên liệu tên lửa, hoả cụ, hoả thuật.', N'VI', N'Công việc rất nguy hiểm, dễ xảy ra cháy nổ, chịu tác động của dung môi độc hại, hơi a xít, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10112, N'001234', N'Thí nghiệm, thử nghiệm, sản xuất đo đạc đánh giá chất lượng và tính năng các thành phần của đạn dược, tên lửa, ngư lôi, thuỷ lôi (ngòi nổ, bộ lửa...).', N'VI', N'Công việc rất nguy hiểm, độc hại căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10113, N'001235', N'Nghiên cứu, thí nghiệm, chế thử, thử nghiệm và sản xuất các thành phần và tổng lắp ngòi đạn, thân đạn, đạn dược, tên lửa, ngư lôi, thuỷ lôi...', N'VI', N'Công việc rất nguy hiểm, dễ xảy ra cháy nổ, thường xuyên tiếp xúc với hơi a xít, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10114, N'001236', N'Nghiên cứu, chế tạo thuốc đen và những sản phẩm, bộ phận, chi tiết đạn dược có dùng thuốc đen.', N'VI', N'Công việc rất nguy hiểm, dễ xảy ra cháy nổ, thường xuyên tiếp xúc thuốc và hoá chất độc, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10115, N'001237', N'Nghiên cứu, chế tạo các loại thuốc nổ, hoả cụ, hoả thuật và các sản phẩm trung gian.', N'VI', N'Công việc rất nguy hiểm, dễ xảy ra cháy nổ, thường xuyên tiếp xúc với các loại hoá chất độc mạnh (hơi A xít đặc, các ô xít Nitơ, thuỷ ngân), căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10116, N'001238', N'Nghiên cứu, chế tạo, tái sinh đúc ép nhồi thuốc nổ mạnh vào các loại đạn, bom, mìn, ngòi nổ.', N'VI', N'Công việc rất nguy hiểm, thường xuyên tiếp xúc với hoá chất độc, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10117, N'001239', N'Nghiên cứu, điều chế thuốc phóng, nhiên liệu tên lửa.', N'VI', N'Công việc rất nguy hiểm do cháy nổ, thường xuyên tiếp xúc với bụi thuốc, hơi hoá chất độc, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10118, N'001240', N'Nghiên cứu, thí nghiệm, chế thử, thử nghiệm, kiểm tra chất lượng, sửa chữa, bảo quản, bốc xếp, điều chuyển đạn dược.', N'VI', N'Công việc rất nguy hiểm do cháy nổ, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10119, N'001241', N'Thợ sản xuất thuốc phóng, thuốc nổ.', N'VI', N'Thường xuyên tiếp xúc với hoá chất độc hại, nguy hiểm, nơi làm việc thiếu dưỡng khí, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10120, N'001242', N'Thợ sản xuất nguyên liệu, sản phẩm trung gian để sản xuất thuốc phóng, thuốc nổ.', N'VI', N'Thường xuyên tiếp xúc với hoá chất độc hại, căng thẳng thị giác và mệt mỏi thần kinh, độc hại, công việc nguy hiểm, dễ cháy nổ.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10121, N'001243', N'Nghiên cứu, chế thử, sản xuất, xử lý, thử nghiệm thuốc nổ TNT.', N'VI', N'Công việc rất nguy hiểm dễ xảy ra cháy nổ, thường xuyên tiếp xúc với các loại hoá chất.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10122, N'001244', N'Nghiên cứu, thiết kế, thí nghiệm, hiệu chỉnh, thử nghiệm hệ thống tên lửa, ra đa, súng pháo, tác chiến điện tử và hệ thống thông tin trên tàu chiến, vũ khí dưới nước.', N'VI', N'Ánh hưởng của sóng siêu cao tần công suất lớn, chịu tác động của ồn, nóng, rung, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10123, N'001245', N'Sản xuất, thử nghiệm, phân tích, kiểm nghiệm các loại pháo hoa, pháo hoa nổ.', N'VI', N'Người lao động làm việc không theo giờ cố định. Công việc rất nguy hiểm, dễ cháy nổ, tiếp xúc với thuỷ ngân, hoá chất độc, ảnh hưởng tới hệ thần kinh, tiêu hoá, miễn dịch.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10124, N'001246', N'Bốc xếp đạn dược, nhiên liệu lỏng tên lửa.', N'V', N'Công việc nặng nhọc, rất nguy hiểm (dễ cháy nổ), tiếp xúc hóa chất độc hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10125, N'001247', N'Lái, phụ xe áp tải xe chở đạn dược, nhiên liệu lỏng tên lửa.', N'V', N'Rất nguy hiểm (dễ cháy nổ), tiếp xúc ồn, rung xóc căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10126, N'001248', N'Thủ kho, bảo quản đạn dược, nhiên liệu lỏng tên lửa.', N'V', N'Rất nguy hiểm (dễ cháy nổ), tiếp xúc hóa chất độc hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10127, N'001249', N'Nhiệt luyện nòng súng trong lò chì.', N'V', N'Công việc độc hại, thường xuyên tiếp xúc với hơi chì, nóng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10128, N'001250', N'Sử dụng sơn, keo trong dung môi độc khi lắp ghép, chế tạo những chi tiết đạn dược.', N'V', N'Nguy hiểm (dễ cháy nổ), tiếp xúc hóa chất độc mạnh. (axêton, êtyl, axêtat, butyl aetat), căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10129, N'001251', N'Sản xuất chi tiết bộ phận vũ khí, đạn dược bằng nhựa, cốt bông thủy tinh.', N'V', N'Nóng, rất độc hại (bụi bông thủy tinh, hơi độc của fenol, phoomađêhit axít ôlêíc).', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10130, N'001252', N'Nắn, tống sát chì nòng súng.', N'V', N'Tư thế lao động gò bó, tiếp xúc nóng, hóa chất độc hại, căng thẳng thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10131, N'001253', N'Sản xuất, thử nghiệm vũ khí, khí tài sau sản xuất, sửa chữa và cải tiến.', N'V', N'Nguy hiểm, tiếp xúc hoá chất độc hại, ồn và bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10132, N'001254', N'Sản xuất các loại đạn dược, hoả cụ huấn luyện.', N'V', N'Thường xuyên tiếp xúc với hoá chất độc hại, nguy hiểm, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10133, N'001255', N'Nấu, trộn, tẩm, ép định hình và thiêu kết sản phẩm hợp kim cứng sản xuất các chi tiết súng, đạn.', N'V', N'Nơi làm việc rất nóng, rung, ồn, thường xuyên tiếp xúc bụi kim loại siêu mịn và hỗn hợp hoá chất (Cô ban; Các bít; C02 A1203), căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10134, N'001256', N'Chỉ huy, tham mưu, theo dõi, chỉ đạo, điều hành công tác bảo quản, bảo dưỡng, sửa chữa, bốc xếp ở kho đạn, kho ngư lôi, thuỷ lôi, bom phóng, bom chìm.', N'V', N'Làm việc trong môi trường rất dễ xảy ra cháy nổ, căng thẳng thần kinh.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10135, N'001257', N'Nghiên cứu, sản xuất, thử nghiệm vũ khí, khí tài sau sản xuất, sửa chữa và cải tiến.', N'V', N'Công việc nguy hiểm, thường xuyên tiếp xúc hoá chất độc, tiếng ồn và bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10136, N'001258', N'Vệ sinh công nghiệp khu vực sản xuất, sửa chữa, thử nghiệm đạn dược.', N'V', N'Làm việc nài trời, nguy hiểm, độc hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10137, N'001259', N'Xử lý chất thải công nghiệp trong điều chế thuốc phóng, thuốc nổ; hủy thuốc phóng, thuốc nổ.', N'V', N'Công việc nặng nhọc, độc hại, nguy hiểm, thường xuyên tiếp xúc với khí độc, nóng, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10138, N'001260', N'Cảnh vệ, bảo vệ kho nhiên liệu lỏng tên lửa (kho 0, G).', N'V', N'Công việc nguy hiểm, ảnh hưởng nồng độ hoá chất độc rất cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10139, N'001261', N'Quản lý, kiểm tra, đánh giá thiết kế về tiêu chuẩn vũ khí, đạn dược.', N'V', N'Công việc rất nguy hiểm, dễ xảy ra cháy nổ, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10140, N'001262', N'Lái xe đặc chủng vận chuyển mẫu thí nghiệm, vũ khí đạn dược, hoá chất phục vụ kiểm định vũ khí đạn dược.', N'V', N'Công việc độc hại, nguy hiểm thường xuyên tiếp xúc với hóa chất nguy hiểm, dễ cháy nổ như: nhiên liệu lỏng, thuốc phóng, thuốc nổ.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10141, N'001263', N'Quản lý, bảo quản, bảo dưỡng, sửa chữa vật tư kỹ thuật tên lửa và đạn tên lửa chống tăng.', N'V', N'Công việc nguy hiểm, thường xuyên tiếp xúc với hoá chất độc hại, căng thẳng thần kinh.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10142, N'001264', N'Nấu rót gang thép để sản xuất các chi tiết vũ khí, đạn.', N'V', N'Công việc nặng nhọc, nguy hiểm, chịu tác động của nóng và hơi khí độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10143, N'001265', N'Cán thép nóng để sản xuất các chi tiết vũ khí, đạn.', N'V', N'Thường xuyên tiếp xúc với nóng, chịu tác động của bụi, ồn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10144, N'001266', N'Nấu đúc phôi nhôm, đồng để sản xuất các chi tiết vũ khí, đạn.', N'V', N'Công việc nặng nhọc, tư thế gò bó, chịu tác động của nóng, hơi khí độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10145, N'001267', N'Đúc, cán nhôm, đồng, thép nóng để sản xuất các chi tiết vũ khí, đạn.', N'V', N'Công việc nặng nhọc, nơi làm việc rất nóng và ồn vượt tiêu chuẩn cho phép.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10146, N'001268', N'Thợ sơn trong hầm tàu, sơn chống rỉ tàu quân sự.', N'V', N'Môi trường làm việc chật hẹp, thiếu ánh sáng, dưỡng khí.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10147, N'001269', N'Bảo quản, bảo dưỡng vật tư tăng thiết giáp, xe máy quân sự trên dây chuyền bảo quản hoá.', N'V', N'Làm việc trong nhà nóng, thường xuyên tiếp xúc với hơi khí độc, dầu mỡ, hoá chất.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10148, N'001270', N'Thợ sửa chữa cơ, điện, lắp đặt, bảo dưỡng thiết bị, vận hành máy nén khí, thiết bị lạnh, hơi trong dây chuyền sản xuất thuốc phóng, thuốc nổ và các sản phẩm trung gian.', N'V', N'Môi trường làm việc nóng bức, thường xuyên tiếp xúc khí độc (CO, NO, NO2, SO2, SO3, NH3), hóa chất độc, nơi làm việc thiếu dưỡng khí.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10149, N'001271', N'Xử lý môi trường trong nhà máy sản xuất thuốc phóng, thuốc nổ, nhiên liệu tên lửa và các sản phẩm trung gian.', N'V', N'Công việc nặng nhọc, thường xuyên tiếp xúc với các yếu tố độc hại như: hơi khí độc (NO, NO2, SO2, SO3, NH3), hoá chất độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10150, N'001272', N'Nhiệt luyện chi tiết vũ khí.', N'V', N'Nóng, tiếp xúc với bức xạ nhiệt, hơi khí độc, tiêu hao năng lượng, chịu tải cơ bắp.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10151, N'001273', N'Làm việc trên đốc nổi (đốc nổi trên sông) đóng tàu quân sự.', N'V', N'Thường xuyên làm việc trong hầm chật hẹp, thiếu dưỡng khí, chịu tác động của nóng và tiếng ồn cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10152, N'001274', N'Vận hành máy xay, nghiền, trộn, cán, đùn, ép, tráng nhựa vật liệu PVC, PE và các loại nhựa khác phục vụ sản xuất các chi tiết vũ khí, đạn, trang bị chống đạn, nghi binh, nghi trang quân sự.', N'V', N'Công việc độc hại, thường xuyên tiếp xúc với bụi, hơi và khí độc, nhiệt độ cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10153, N'001275', N'Thủ kho, bảo quản, bốc xếp, thuốc phóng, thuốc nổ và các sản phẩm trung gian.', N'V', N'Người lao động làm việc không theo giờ cố định. Công việc rất nguy hiểm, dễ cháy nổ, tiếp xúc với thuỷ ngân, hoá chất độc, ảnh hưởng tới hệ thần kinh, tiêu hoá, miễn dịch.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10154, N'001276', N'Nấu, luyện chì phục vụ sản xuất, thử nghiệm các sản phẩm quốc phòng.', N'V', N'Người lao động làm việc không theo giờ cố định, môi trường nóng, ảnh hưởng của bức xạ nhiệt và hơi chì độc hại, ảnh hưởng thị giác, khứu giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10155, N'001277', N'Vận hành máy Xray, máy quang phổ kiểm tra vật liệu sản xuất, sản phẩm quốc phòng.', N'V', N'Người lao động làm việc không theo giờ cố định. Công việc Tiếp xúc trực tiếp với tia X, tia tử nại, căng thẳng thần kinh, thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10156, N'001278', N'Lái xe chở đạn trong kho quân khí.', N'V', N'Làm việc không theo giờ cố định. Công việc đặc biệt nguy hiểm, tiếp xúc hoá chất độc hại, yêu cầu tập trung chú ý cao, căng thẳng thần kinh tâm lý mức độ cao', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10157, NULL, N'Vận hành, kiểm tra, bảo dưỡng, sửa chữa máy Xray, siêu âm, quang phổ trong kiểm tra khuyết tật thuốc nổ trong đạn.', N'V', N'Thường xuyên không theo khung giờ cố định, công việc tiếp xúc trực tiếp với tia X, tia tử nại, sóng siêu âm căng thẳng thần kinh, thị giác. Các tia bức xạ ion hoá cường độ cao xuyên qua sắt thép lớp dầy để kiểm tra lớp trong cùng của sản phẩm quốc phòng', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10158, N'001280', N'Nhân viên tiếp nhận, cấp phát vũ khí, đạn dược phục vụ quốc phòng tại các phân kho vũ khí.', N'V', N'Người lao động làm việc không theo giờ cố định. Công việc rất nguy hiểm, dễ cháy nổ, tiếp xúc với hoá chất độc, nguy cơ cao gây mất an toàn lao động.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10159, N'001281', N'Sửa chữa, bảo dưỡng súng, pháo, khí tài, đạn dược tại các kho tàng, trạm, xưởng bảo dưỡng, sửa chữa vũ khí, khí tài, đạn dược.', N'IV', N'Tiếp xúc dầu mỡ, hóa chất độc hại, tập trung chú ý cao, tư thế lao động gò bó.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10160, N'001282', N'Báo bia chuyên nghiệp ở các trạm, xưởng sản xuất và sửa chữa vũ khí.', N'IV', N'Nguy hiểm, tư thế làm việc gò bó, chật hẹp, chịu tác động của ồn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10161, N'001283', N'Sản xuất sửa chữa khí tài quang học, máy đo xa, trinh xa.', N'IV', N'Tiếp xúc bụi nước thủy tinh, tiếp xúc cồn, ête, căng thẳng thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10162, N'001284', N'Bảo vệ, cảnh vệ trong kho và khu vực sản xuất đạn dược.', N'IV', N'Phải đi lại nhiều không kể ngày đêm, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10163, N'001285', N'Thủ kho, bảo quản, bốc xếp vũ khí trong kho vũ khí.', N'IV', N'Thường xuyên tiếp xúc dầu mỡ, nóng, hóa chất độc hại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10164, N'001286', N'Vận hành, sửa chữa, lắp đặt bổ sung thiết bị; sửa chữa công trình nhà xưởng khu vực sản xuất và kho đạn dược.', N'IV', N'Tiếp xúc thường xuyên với yếu tố nguy hiểm, độc hại, công việc đòi hỏi phải tập trung chú ý cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10165, N'001287', N'Bảo vệ, cảnh vệ trong kho vũ khí, vật liệu nổ.', N'IV', N'Làm việc nài trời, đi lại nhiều tiêu hao năng lượng, tiếp xúc vi sinh vật có hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10166, N'001288', N'Trực tiếp chỉ huy kỹ thuật sản xuất đạn dược.', N'IV', N'Công việc nặng nhọc nguy hiểm, tiếp xúc thường xuyên yếu tố độc hại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10167, N'001289', N'Vệ sinh công nghiệp khu vực sản xuất đạn dược.', N'IV', N'Tiếp xúc thường xuyên với yếu tố nguy hiểm, độc hại, công việc nặng nhọc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10168, N'001290', N'Gia công thiết bị quang học quân sự (mài, khắc, mạ, dán); lắp ráp khí tài quân sự (lắp cơ, lắp quang).', N'IV', N'Thường xuyên tiếp xúc với cồn, ête và các chất phụ liệu quang học độc hại, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10169, N'001291', N'Khoan tia lửa điện, xung điện, cắt bằng dây CNC.', N'IV', N'Môi trường làm việc thiếu ô xy, thường xuyên tiếp xúc khí dầu và kim loại cháy, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10170, N'001292', N'Trực tiếp theo dõi, chỉ đạo, điều hành công tác bảo quản, bảo dưỡng, sửa chữa, bốc xếp ở kho vũ khí.', N'IV', N'Thường xuyên tiếp xúc với chất độc hại, nguy hiểm.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10171, N'001293', N'Quản lý, xử lý, tiêu huỷ các loại vũ khí cấp 5.', N'IV', N'Làm việc nài trời, nguy hiểm, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10172, N'001294', N'Sản xuất, sửa chữa, sơn hòm hộp, bao gói vũ khí, khí tài, đạn dược.', N'IV', N'Nơi làm việc ồn, bụi, tiếp xúc với hóa chất độc hại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10173, N'001295', N'Nhuộm đen, lân, mạ, sơn vũ khí, khí tài quang học; Đun nấu, pha chế dầu mỡ, hoá chất trong bảo quản, sản xuất vũ khí, chi tiết quân sự.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc hại, nguy hiểm, nóng, ồn và bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10174, N'001296', N'Thợ sửa chữa trang thiết bị trạm hoá thí nghiệm thuốc phóng, thuốc nổ.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc hại, nguy hiểm, nóng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10175, N'001297', N'Thủ kho, thống kê, bảo quản, bốc xếp vật tư hoá chất phục vụ huấn luyện, thí nghiệm đạn dược, chất cháy quân sự.', N'IV', N'Công việc nặng nhọc, tiếp xúc với hoá chất độc hại, rất nguy hiểm.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10176, N'001298', N'Thợ sửa chữa xe xích.', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với dầu mỡ, hoá chất, tư thế gò bó.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10177, N'001299', N'Giám sát thi công quá trình hàn kết cấu, làm sạch và sơn thân vỏ tàu quân sự.', N'IV', N'Thường xuyên làm việc nài trời, nắng, nóng, căng thẳng thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10178, N'001300', N'Nghiên cứu, chế thử sản xuất các loại trụ gốm áp điện PZT chi tiết vũ khí.', N'IV', N'Làm việc ở nơi có nhiệt độ cao, tiếp xúc với bụi kim loại và axít.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10179, N'001301', N'Nhân viên thống kê trong kho vũ khí, đạn dược.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc hại, nguy hiểm.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10180, N'001302', N'Sản xuất hộp giấy, ống giấy bảo quản đạn.', N'IV', N'Tiếp xúc với hoá chất độc hại, môi trường bụi, ồn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10181, N'001303', N'Nhân viên kiểm định dưỡng đo kiểm súng pháo, khí tài, đạn dược, phương tiện đo chuyên dùng trong kiểm định súng pháo, khí tài, đạn dược.', N'IV', N'Thường xuyên làm việc trong phòng kín, tiếp xúc với xăng dầu, hoá chất độc hại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10182, N'001304', N'Thủ kho, thống kê, bảo quản, bốc xếp vật tư, hoá chất phục vụ cho bảo quản, bảo dưỡng vũ khí khí tài, đạn dược.', N'IV', N'Thường xuyên tiếp xúc với dầu mỡ, hoá chất độc hại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10183, N'001305', N'Sản xuất túi dầu khô, trang cụ, giấy bảo quản súng pháo kỹ thuật đạn dược.', N'IV', N'Công việc thủ công thường xuyên tiếp xúc với dầu mỡ ở nhiệt độ cao, bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10184, N'001306', N'Nhân viên tu bổ, sửa chữa nhà kho cất chứa vũ khí.', N'IV', N'Thường xuyên tiếp xúc với môi trường độc hại, tư thế làm việc gò bó.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10185, N'001307', N'Thợ nạp bình khí nén, bình cứu hoả, sấy Silicagen phục vụ vũ khí đạn dược.', N'IV', N'Tư thế làm việc gò bó, căng thẳng thần kinh.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10186, N'001308', N'Thủ kho, bảo quản, bốc xếp trong kho trang bị vật tư kỹ thuật tên lửa khí tài đặc chủng.', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với hoá chất độc hại, nguy hiểm, tư thế làm việc gò bó, căng thẳng thần kinh.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10187, N'001309', N'Thủ kho, bảo quản, bốc xếp trong kho trang bị vật tư xe máy, trạm nguồn điện trong kho vật tư, xe máy quân sự dự trữ quốc phòng và dự trữ quốc gia', N'IV', N'Luôn tiếp xúc với dầu mỡ, tư thế gò bó.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10188, N'001310', N'Thợ sửa chữa, nạp điện ắc qui cho xe, máy quân sự trong kho xe dự trữ quốc phòng và dự trữ quốc gia.', N'IV', N'Làm việc thủ công, luôn tiếp xúc với hoá chất.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10189, N'001311', N'Lái xe, phụ xe, áp tải chở thuốc phóng, thuốc nổ, nhiên liệu tên lửa và các sản phẩm trung gian.', N'IV', N'Công việc nặng nhọc, nguy hiểm, bụi, ồn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10190, N'001312', N'Làm khuôn đúc gang thép để sản xuất các chi tiết vũ khí.', N'IV', N'Nóng, ồn, bụi, làm việc ca kíp.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10191, N'001313', N'Sàng, trộn cát làm khuôn đúc để sản xuất các chi tiết vũ khí.', N'IV', N'Nặng nhọc, ồn, bụi, làm việc ca kíp.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10192, N'001314', N'Lấy mẫu, phân tích sản phẩm kim loại để sản xuất các chi tiết vũ khí.', N'IV', N'Hơi khí độc, làm việc ca kíp.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10193, N'001315', N'Vận hành điện lò nấu thép để sản xuất các chi tiết vũ khí.', N'IV', N'Nóng, ồn, bụi, làm việc ca kíp.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10194, N'001316', N'Nhiệt luyện kim loại (ủ, tôi, ram) để sản xuất các chi tiết vũ khí, đạn.', N'IV', N'Công việc nặng nhọc, rất nóng ảnh hưởng của bức xạ, của CO, CO2, SO2 và ồn rất cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10195, N'001317', N'Mạ chi tiết vũ khí, ngòi đạn (Niken, Crôm, Kẽm).', N'IV', N'Thường xuyên tiếp xúc với các loại hoá chất độc hại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10196, N'001318', N'Đốt lò, vận hành lò hơi phục vụ sản xuất các loại vũ khí đạn.', N'IV', N'Công việc nặng nhọc, rất nóng, ảnh hưởng của bức xạ nhiệt, bụi than có nồng độ cao, tiếng ồn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10197, N'001319', N'Nhiệt luyện kim loại cho các chi tiết vũ khí đạn.', N'IV', N'Công việc nặng nhọc, rất nóng, bụi, ồn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10198, N'001320', N'Tẩy rửa, ủ, lân hoá, nhuộm mầu kim loại và các sản phẩm kim loại bằng hoá chất của các chi tiết vũ khí.', N'IV', N'Thường xuyên tiếp xúc với các loại hoá chất, Axít và xút.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10199, N'001321', N'Ép nhựa các chi tiết vũ khí, ngòi đạn.', N'IV', N'Thường xuyên tiếp xúc với nóng, bụi và hơi khí độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10200, N'001322', N'Nấu đúc gang phục vụ sản xuất vũ khí.', N'IV', N'Công việc nặng nhọc, nguy hiểm, chịu tác động của nóng, bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10201, N'001323', N'Nung kim loại bằng lò cao tần trong các nhà máy sản xuất vũ khí.', N'IV', N'Công việc nặng nhọc, chịu tác động của nóng, bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10202, N'001324', N'Sơn bằng phương pháp thủ công, sơn cách điện, sấy động cơ điện các chi tiết vũ khí, đạn.', N'IV', N'Thường xuyên tiếp xúc với các hoá chất độc trong sơn; tư thế lao động gò bó.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10203, N'001325', N'Sửa chữa cơ, điện máy, các máy công cụ sản xuất các chi tiết vũ khí.', N'IV', N'Làm việc trong môi trường hoá chất độc hại, tư thế lao động gò bó.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10204, N'001326', N'Hàn các chi tiết vũ khí bằng phương pháp nung chảy.', N'IV', N'Công việc nặng nhọc, tư thế lao động gò bó, chịu tác động của nóng và khí độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10205, N'001327', N'Ép suất thành hình săm, lốp ô tô, lốp pháo.', N'IV', N'Công việc nặng nhọc, tiếp xúc với nhiệt độ cao, các hoá chất và dung môi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10206, N'001328', N'Giám sát đóng tàu quân sự.', N'IV', N'Thường xuyên làm việc nài trời, chịu ảnh hưởng của hơi khí độc, bức xạ nhiệt, bụi ồn, rung, căng thẳng thần kinh, tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10207, N'001329', N'Khảo sát đánh giá chất lượng để sửa chữa hoán cải tàu quân sự.', N'IV', N'Môi trường làm việc dưới độ sâu, thiếu dưỡng khí, độc hại, nguy hiểm, căng thẳng thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10208, N'001330', N'Cảnh vệ, bảo vệ trong nhà máy sản xuất thuốc phóng, thuốc nổ, nhiên liệu tên lửa và các sản phẩm trung gian.', N'IV', N'Làm việc nài trời, thường xuyên tiếp xúc với', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10209, N'001331', N'Hàn vỏ tàu quân sự.', N'IV', N'Hàn nài trời, nóng, tư thế lao động gò bó, ảnh hưởng của C02.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10210, N'001332', N'Lái cẩu điện, cẩu diezen; lái xe đầu kéo có rơ mooc ở cảng.', N'IV', N'Chịu tác động của ồn, bụi, nóng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10211, N'001333', N'Sửa chữa máy tàu (ở âu, đà).', N'IV', N'Công việc nặng nhọc, nóng, ẩm ướt thường xuyên tiếp xúc với dầu mỡ.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10212, N'001334', N'Hoá nhôm (mạ nhôm, Anod hóa nhôm)', N'IV', N'Tiếp xúc với khí độc, làm việc theo ca kíp.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10213, N'001335', N'Mạ kim loại và Xyanua chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, tiếp xúc với hơi độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10214, N'001336', N'Vận hành lò hơi phục vụ sản xuất vũ khí.', N'IV', N'Công việc nặng nhọc, bụi, ồn và nóng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10215, N'001337', N'Đột, dập nóng chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, chịu tác động của bức xạ nhiệt và ồn rất cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10216, N'001338', N'Làm sạch vật đúc để sản xuất các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, chịu tác động của nóng, ồn, bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10217, N'001339', N'Lái cầu trục trong phân xưởng đúc cơ khí để phục vụ sản xuất các chi tiết vũ khí.', N'IV', N'Nóng, bụi, căng thẳng thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10218, N'001340', N'Mạ kẽm, Crôm, Chì, Niken các chi tiết vũ khí.', N'IV', N'Chịu tác động của nhiều loại khí, hóa chất độc như HCl, NHI, NH4OH, NH4Cl, ZnO và chì.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10219, N'001341', N'Hàn điện, hàn hơi phục vụ sản xuất các chi tiết vũ khí.', N'IV', N'Tiếp xúc với nóng và hơi khí độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10220, N'001342', N'Vận hành máy nén khí áp lực từ (8kg/cm2) trở lên để sản xuất và sửa chữa các chi tiết vũ khí.', N'IV', N'Chịu ảnh hưởng của rung và tiếng ồn rất cao', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10221, N'001343', N'Vận hành búa máy đế sản xuất các chi tiết vũ khí.', N'IV', N'Chịu tác động của nhiệt độ cao, rung động lớn và tiếng ồn vượt tiêu chuẩn cho phép.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10222, N'001344', N'Cán nhôm lạnh để sản xuất các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, tư thế lao động gò bó, chịu tác động của tiếng ồn cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10223, N'001345', N'Nung, ép định hình đồng, nhôm để sản xuất các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, chịu tác động của tiếng ồn và hơi khí độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10224, N'001346', N'Kéo dây đồng và nhôm để phục vụ sản xuất các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, tiếp xúc với tiếng ồn lớn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10225, N'001347', N'Hấp, ủ nhôm để phục vụ sản xuất các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, nóng, thường xuyên làm việc trong môi trường bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10226, N'001348', N'Sơn tĩnh điện để phục vụ sản xuất các chi tiết vũ khí.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc, nóng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10227, N'001349', N'Mài khô kim loại các chi tiết vũ khí.', N'IV', N'Tiếp xúc với bụi đá mài, bụi kim loại và tiếng ồn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10228, N'001350', N'Chà sáng, cạo rỉ, đánh bóng các chi tiết vũ khí bằng kim loại.', N'IV', N'Tư thế lao động gò bó, thường xuyên chịu tác động của ồn, bụi nồng độ cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10229, N'001351', N'Khoan, phay, bào, tiện gang các chi tiết vũ khí.', N'IV', N'Căng thẳng thị giác, tập trung chú ý cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10230, N'001352', N'Bả ma tít và sơn xì thân máy các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, chịu tác động của dung môi pha sơn và hơi xăng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10231, N'001353', N'Rèn búa máy từ 350 kg trở lên để sản xuất các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, nóng và tiếng ồn rất cao, ảnh hưởng đến thính giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10232, N'001354', N'Công nhân vận hành trạm biến thế từ 110 KV trở lên phục vụ sản xuất vũ khí, đạn.', N'IV', N'Căng thẳng thần kinh tâm lý, chịu tác động của điện từ trường cao, ảnh hưởng nhiều đến sức khoẻ', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10233, N'001355', N'Rèn thủ công các chi tiết vũ khí.', N'IV', N'Công việc thủ công, nặng nhọc, chịu tác động của nóng, bụi và khí CO.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10234, N'001356', N'Phá khuôn đúc bằng chày hơi sản xuất các chi tiết vũ khí đạn.', N'IV', N'Nặng nhọc, nóng, bụi, rung.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10235, N'001357', N'Vận hành máy đột dập kim loại sản xuất các chi tiết vũ khí.', N'IV', N'Nóng, ồn, rung, căng thẳng thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10236, N'001358', N'Đốt, vận hành lò ủ kim loại để sản xuất các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, độc hại, thường xuyên chịu tác động của nhiệt độ cao, CO và CO2.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10237, N'001359', N'Vận hành máy dập, dũa, mài bi kim loại để sản xuất các chi tiết vũ khí.', N'IV', N'Thường xuyên tiếp xúc với rung, ồn và hoá chất độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10238, N'001360', N'Tiện gang các chi tiết thân đạn.', N'IV', N'Bụi, căng thẳng thị giác, tập trung chú ý cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10239, N'001361', N'Tráng, sơn cách điện dây điện của các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, chịu tác động của tiếng ồn và hơi khí độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10240, N'001362', N'May công nghiệp, may khâu da hàng quân sự.', N'IV', N'Tư thế lao động gò bó, công việc đơn điệu, căng thẳng thị giác và mệt mỏi thần kinh tâm lý.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10241, N'001363', N'Cán tráng, cán hình vải cao su các chi tiết vũ khí.', N'IV', N'Ảnh hưởng của ồn, xăng và SO2.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10242, N'001364', N'Lưu hoá các sản phẩm cao su các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, tiếp xúc với các hoá chất độc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10243, N'001365', N'Chế tạo, sản xuất ống cao su chịu áp lực thuộc các chi tiết vũ khí.', N'IV', N'Nặng nhọc, tiếp xúc với các hoá chất xúc tác, lưu huỳnh.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10244, N'001366', N'Sửa chữa cơ, điện các máy công cụ, máy in, xén tài liệu quân sự.', N'IV', N'Làm việc trong môi trường có hoá chất độc, tư thế lao động gò bó.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10245, N'001367', N'Sản xuất, quấn ống giấy bao gói vật liệu nổ phục vụ sản xuất hàng quân sự.', N'IV', N'Chịu tác động của nóng, hoá chất độc, bụi trong suốt ca làm việc.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10246, N'001368', N'Lái xe vận tải chuyên dùng chở hoá chất phục vụ sản xuất quốc phòng.', N'IV', N'Chịu tác động của ồn, rung, hoá chất độc, nguy hiểm, căng thẳng thần kinh.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10247, N'001369', N'Hoá nghiệm, kiểm tra chất lượng hoá chất phục vụ sản xuất quốc phòng.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc hại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10248, N'001370', N'Đo lường, kiểm định, hiệu chỉnh và sửa chữa phương tiện đo trong dây chuyền sản xuất vũ khí, đạn, thuốc phóng, thuốc nổ, nhiên liệu tên lửa và các sản phẩm trung gian.', N'IV', N'Công việc nặng nhọc; thường xuyên tiếp xúc với các hóa chất độc hại như: NO, NO2, SO2, SO3, DNT, DBP, Xentralit, ête.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10249, N'001371', N'Sản xuất mạch in thuộc các chi tiết vũ khí.', N'IV', N'Thường xuyên tiếp xúc với hoá chất (mạ đồng, mạ thiếc, chất ăn mòn FeCl3; Axêtôn, Benzen...) và các dung dịch rửa phim, hãm ảnh, tẩy cản quang.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10250, N'001372', N'Sản xuất khí phục vụ quốc phòng.', N'IV', N'Công việc nặng nhọc, làm việc trong môi trường nguy hiểm, có nguy cơ cháy, nổ cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10251, N'001373', N'Sản xuất ống khuếch đại ánh sáng thuộc các chi tiết vũ khí.', N'IV', N'Thường xuyên tiếp xúc với hoá chất như: H2SO4, HNO3, TCE...', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10252, N'001374', N'Hàn lăn các chi tiết vũ khí.', N'IV', N'Công việc nặng nhọc, tư thế gò bó, thường xuyên tiếp xúc với dung dịch làm mát cực máy hàn.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10253, N'001375', N'Siêu âm từ tính chi tiết vũ khí.', N'IV', N'Tiếp xúc hơi khí độc, bức xạ điện từ, căng thẳng thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10254, N'001376', N'Thiết kế tàu quân sự (tính toán kết cấu, lập bản tính, bản vẽ, tính toán kiểm tra độ bền kết cấu).', N'IV', N'Quá trình làm việc bị tiêu hao năng lượng, thao tác đơn điệu, căng thẳng thị giác, thần kinh mệt mỏi và gánh nặng thông tin.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10255, N'001377', N'Lắp đặt, thử khi chế tạo độ bền các chi tiết kết cấu tàu quân sự.', N'IV', N'Điều kiện làm việc có độ ồn lớn, âm thanh chói từ va chạm, chà sát kim loại, các khí thải công nghiệp và bụi kim loại.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10256, N'001378', N'Vận hành hệ thống cấp nước, điện phục vụ cho sản xuất thuốc phóng, thuốc nổ, nhiên liệu tên lửa và các sản phẩm trung gian.', N'IV', N'Môi trường làm việc ồn, rung.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10257, N'001379', N'Thủ kho, bốc xếp tại kho chứa sản phẩm pháo hoa, pháo hoa nổ.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc rất nguy hiểm, dễ cháy nổ, tiếp xúc với thuỷ ngân, hoá chất độc, ảnh hưởng tới hệ thần kinh, tiêu hoá, miễn dịch.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10258, N'001380', N'Nhúng dung dịch keo hỗn hợp tạo khuôn đúc mẫu chảy các chi tiết vũ khí đạn, tên lửa.', N'IV', N'Người lao động làm việc không theo giờ cố định. Thường xuyên tiếp xúc với môi trường nóng bức, thường xuyên tiếp xúc với hoá chất độc hại nồng độ cao, tư thế lao động gò bó, căng thẳng thần kinh tâm lý', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10259, N'001381', N'Vận hành, sửa chữa máy tiện băng dài, máy rèn, máy khoan, máy doa sâu sản xuất nòng súng.', N'IV', N'Người lao động làm việc không theo giờ cố định, môi trường có tiếng ồn lớn, rung động lớn, tư thế lao động gò bó, tiếp xúc với dầu mỡ.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10260, NULL, N'Vận hành máy cắt laze, vận hành máy ép thuỷ lực sản xuất trang bị chống đạn.', N'IV', N'Làm việc không theo giờ cố định, tư thế lao động gò bó chịu tác động của nóng, khói bụi, tiếng ồn, nhiệt độ, áp suất cao (lò hơi), tiếp xúc hóa chất độc hại: sử dụng vật liệu keo 830, 1430 + bột, cát (cát zircon, bột zircon, cát Mã Lai, bột Mã Lai) ; hoá chất phụ gia khử bọt, thấm ướt để đúc PG9, OG9, chi tiết tên lửa Igla…', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10261, N'001383', N'Ép sáp các chi tiết vũ khí, đạn.', N'IV', N'Làm việc không theo giờ cố định, công việc nguy hiểm rủi ro khi đóng mở khuôn, vệ sinh máy ép, thay khuôn. Tiếp xúc hoá chất độc hại (chất chống dính khuôn), nguy cơ viêm da, dị ứng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10262, N'001384', N'Vận hành máy dán có tần số siêu âm phục vụ sản xuất nghi binh, nghi trang quân sự.', N'IV', N'Làm việc không theo giờ cố định, tiếp xúc với tiếng ồn, sóng siêu âm, khí độc, căng thẳng thần kinh, thị giác.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10263, N'001385', N'Vận hành, sửa chữa máy kéo sợi, máy dệt phục vụ sản xuất nghi binh, nghi trang quân sự.', N'IV', N'Người lao động làm việc không theo giờ cố định, tiếp xúc với tiếng ồn, hơi nóng, hơi khí độc, căng thẳng thần kinh, thị giác..', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10264, NULL, N'Quấn ống phóng composite phục vụ sản xuất vũ khí đạn.', N'IV', N'Làm việc không theo giờ cố định, tư thế lao động gò bó chịu tác động của bụi thủy tinh trong quá trình cắt quấn tiện, nguội bề mặt; hơi keo khi pha keo, quấn ống, tiếp xúc trực tiếp với da do bụi thủy tinh khuếch tán trong không khí. Sử dụng vật liệu vải sợi composite, keo epoxy, đóng rắn epoxy phoenix, epoxy hardener 8211, vừa cuốn vừa đổ keo ống phóng sản phẩm súng.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10265, NULL, N'Xử lý mặt nài bằng hoá chất các chi tiết cơ khí phục vụ sản xuất quốc phòng.', N'IV', N'Người lao động làm việc không theo giờ cố định. Môi trường làm việc luôn có khí SO2; NO2; NO. thường xuyên tiếp xúc với các loại hóa chất tẩy rửa, axit, chất oxy hoá mạnh. làm việc trong môi trường nóng (các bàn sấy, bể tẩy rửa gia nhiệt); ẩm ướt do tiếp xúc với các dung dịch tẩy rửa.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10266, NULL, N'Hướng dẫn thực hành, đào tạo nghề cho học viên trên các máy tiện, máy phay, máy mài, máy khoan, máy rèn, máy hàn, lò nhiệt luyện, lò nấu kim loại, dây chuyền mạ, phòng thí nghiệm hóa học.', N'IV', N'Người lao động làm việc không theo giờ cố định, môi trường có nhiệt độ cao, khói bụi, ánh sáng khi hàn, hoá chất độc hại, tiếng ồn lớn, dầu mỡ; tiếp xúc các hoá chất như axit clohydric, natri hydroxit, hóa chất mạ (như kẽm sunfat, niken sunfat, đồng sunfat), chất tẩy dầu mỡ, chất làm bóng, chất thụ động hóa', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10267, NULL, N'Nghiên cứu, chế thử, chế tạo, thử nghiệm các bộ phận tên lửa và tổ hợp tên lửa tại các Viện nghiên cứu.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nguy hiểm, dễ cháy nổ, nhiệt độ cao, áp suất cao (300 - 1200 at), ni tơ lỏng (-1960ºC). Tiếp xúc với hoá chất độc hại (thuỷ ngân, Thallium, axit và các hoá chất, các loại sơn, keo đặc chủng, hợp chất tẩy rửa làm sạch sản phẩm.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10268, NULL, N'Nghiên cứu, chế thử, thử nghiệm sơn, các chi tiết cao su, thực hiện anod hoá nhôm phục vụ hàng quân sự; Nghiên cứu, chế thử, thử nghiệm, phôi ống composit từ vải, sợi thuỷ tinh dùng cho sản xuất vũ khí tại các Viện nghiên cứu.', N'IV', N'Người lao động làm việc không theo giờ cố định. Làm việc trong môi trường tiếp xúc hóa chất độc hại (axitsunfuric, oxalic, phosphoric, dung môi hữu cơ, epoxy, chất đóng rắn, dung môi, sợi thủy tinh gây kích ứng, kim loại nặng, phụ gia chống ăn mòn…). Bụi, khí độc (khí SO₂, bụi mịn, hơi hóa chất, bụi sợi thủy tinh). Tiếng ồn (thiết bị khuấy, máy thử nghiệm, máy ép, máy cán cao su).', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10269, N'001391', N'Vận hành máy cắt, máy may, máy in, vận hành dây chuyền bán tự động và tự động trong sản xuất bao bì bảo quản thuốc nổ.', N'IV', N'Làm việc không theo giờ cố định. Công việc chịu tác động của nóng, ồn, bụi, tư thế lao động gò bó. Tiếp xúc với tiếng ồn lớn, nhiệt độ cao và bụi, hơi khí độc: xylen, axeton, flexo', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10270, N'001392', N'Trực tiếp chỉ huy kỹ thuật, kiểm tra, giám sát an toàn trong dây chuyền sản xuất thuốc phóng, thuốc nổ và các sản phẩm trung gian.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc có nguy cơ cháy nổ, mất an toàn, tiếp xúc với các loại hóa chất độc hại, tiếng ồn lớn', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10271, N'001393', N'Sản xuất dụng cụ, sửa chữa máy móc, thiết bị phục vụ công tác bảo dưỡng, bảo quản, sửa chữa, tháo gỡ, xử lý đạn dược.', N'IV', N'Thường xuyên không theo khung giờ cố định khi có nhiệm vụ đặc biệt, chấp hành điều động đột xuất khi có sự cố hỏng hóc máy móc tại các phân xưởng sửa chữa đạn, xử lý đạn, tư thế lao động gò bó chịu tác động của nóng, ồn, bụi.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10272, N'001394', N'Lái xe cẩu, xe công trình, máy công trình trong các kho quân khí', N'IV', N'Thường xuyên không theo khung giờ cố định khi có nhiệm vụ đặc biệt. Thường xuyên làm việc nài trời, chịu ảnh hưởng của rung lắc, tiếng ồn và bụi', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10273, N'001395', N'Vận hành máy tiện, máy phay, máy mài, máy khoan, máy rèn, máy hàn trong sản xuất, sửa chữa, bảo dưỡng các chi tiết vũ khí, đạn dược.', N'IV', N'Làm việc không theo giờ cố định. Làm việc trong môi trường có tiếng ồn lớn, thường xuyên tiếp xúc với dầu mỡ, nóng, ồn, tiếp xúc với hoá chất độc hại, nguy cơ cháy nổ cao.', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10274, N'001396', N'Sơn tĩnh điện các chi tiết vũ khí, đạn dược.', N'IV', N'Công việc nặng nhọc, độc hại, thường xuyên tiếp xúc với hóa chất độc hại, bụi gỉ sắt, tiếng ồn. Nơi làm việc nóng, thiếu không khí, gò bó, căng thẳng thần kinh', 5);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10275, N'001397', N'Mang vác hàng quân sự bằng phương tiện vận tải thô sơ, bằng sức người ở vùng núi cao hiểm trở.', N'VI', N'Làm việc ở vùng đèo dốc, công việc thủ công nặng nhọc nguy hiểm.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10276, N'001398', N'Trực tiếp tìm kiếm, khảo sát, cất bốc, quy tập, vận chuyển hài cốt liệt sỹ.', N'VI', N'Công việc nặng nhọc, làm việc khu vực rừng núi hẻo lánh, độc hại, tiếp xúc với các sinh vật gây bệnh.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10277, N'001399', N'Pháp y quân đội trực tiếp khai quật, mổ tử thi.', N'VI', N'Tiếp xúc với xác chết lâu ngày, dễ nhiễm độc, nhiễm bệnh, căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10278, N'001400', N'Điều khiển xuồng chuyển tải kéo tay ở các đảo xa.', N'VI', N'Công việc nài trời nặng nhọc, nguy hiểm, tiếp xúc với sóng gió, sinh vật có hại.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10279, N'001401', N'Làm việc trong các labor phòng nguyên, phòng hóa, phòng vi sinh vật quân sự.', N'V', N'Tiếp xúc trực tiếp với chất độc, sinh vật có hại, nguy hiểm, có nguy cơ lây nhiễm.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10280, N'001402', N'Sỹ quan, thuyền viên tàu, xà lan vận tải quân sự trên biển.', N'V', N'Công việc nặng nhọc, nguy hiểm, chịu tác động sóng gió, rung, xóc, ồn, căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10281, N'001403', N'Khảo sát, thi công, vận hành, bảo dưỡng, sửa chữa thu hồi kho bể tuyến ống xăng dầu quân sự vùng rừng núi.', N'V', N'Làm việc nài trời, ở các khu vực đèo dốc công việc nặng nhọc, độc hại.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10282, N'001404', N'Trực tiếp chỉ đạo khống chế, dập tắt, tẩy uế các ổ dịch, tẩy uế chiến trường thảm họa.', N'V', N'Tiếp xúc với mầm bệnh, sinh vật có hại, xác chết và hóa chất độc, căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10283, N'001405', N'Ngâm tẩm, phơi gỗ phục vụ cho quân sự.', N'V', N'Công việc thủ công, nặng nhọc, chịu tác động của các hoá chất độc mạnh như a sen, Focmon.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10284, N'001406', N'Bảo quản cụm chi tiết phụ tùng vật tư; vũ khí trang bị kỹ thuật trên dây chuyền bảo quản hoá - Sơn điện di.', N'V', N'Thường xuyên tiếp xúc với hoá chất, dầu mỡ, bụi silic, bụi sơn, gỉ, bột đá, dung môi, cao su.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10285, N'001407', N'Tráng giấy bằng hoá chất bảo quản hàng quân sự.', N'V', N'Công việc nặng nhọc, nguy hiểm, chịu tác động của nhiệt độ cao, hoá chất độc.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10286, N'001408', N'Lái xe ô tô phục vụ đơn vị xe tăng huấn luyện chiến thuật.', N'V', N'Lái xe qua các đường hẹp, đường đèo, dốc nguy hiểm, căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10287, N'001409', N'Nhân viên quân y nghiên cứu, kiểm tra, đo đạc khảo sát môi trường lao động quân sự.', N'V', N'Công việc lưu động, trực tiếp tiếp xúc với hoá chất độc, nguy hiểm.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10288, N'001410', N'Thủ kho, bảo quản, bốc xếp, hóa nghiệm xăng dầu quân sự.', N'V', N'Thường xuyên tiếp xúc xăng, dầu mỡ và các hóa chất độc hại.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10289, N'001411', N'Phun cát, phun bi tẩy rỉ, phun kẽm hàng quân sự.', N'V', N'Thường xuyên tiếp xúc với bụi silic, hơi, khí độc.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10290, N'001412', N'Lực lượng phòng cháy, chữa cháy chuyên trách tại các đơn vị quân đội.', N'V', N'Cường độ làm việc cao, tiêu hao năng lượng lớn, tiếp xúc với nhiều yếu tố nguy hiểm đến tính mạng và căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10291, N'001413', N'Kiểm định viên, kỹ thuật viên kiểm định kỹ thuật an toàn các loại máy, thiết bị, vật tư, chất có yêu cầu nghiêm ngặt về an toàn lao động trong quân đội', N'V', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại, thường xuyên tiếp xúc với hóa chất độc như: Ether, methanol, acid H2SO4 đặc nóng, thủy ngân, benzen, toluen..., nơi làm việc chật hẹp, căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10292, N'001414', N'Đo bức xạ siêu cao tần quốc phòng; xét nghiệm hóa chất công nghiệp quốc phòng.', N'IV', N'Ảnh hưởng tiếng ồn, điện từ trường siêu cao tần và hóa chất độc hại.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10293, N'001415', N'Làm việc trong buồng tăng, giảm áp.', N'IV', N'Chịu ảnh hưởng của áp lực tăng, giảm, thiếu dưỡng khí.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10294, N'001416', N'Sĩ quan, thuyền viên tàu, thuyền xà lan vận tải quân sự đường sông.', N'IV', N'Điều kiện làm việc gò bó, chật hẹp, ẩm ướt, tiếp xúc hóa chất độc hại từ hàng quân sự, ồn.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10295, N'001417', N'Làm việc trong xe tiêu tẩy quân sự.', N'IV', N'Nóng, tiếp xúc hóa chất độc hại.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10296, N'001418', N'Áp tải hàng hóa quân sự theo tàu hỏa, tàu thủy.', N'IV', N'Lựu động theo tàu, chật hẹp, nóng ồn, tiếp xúc yếu tố độc hại nguy hiểm.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10297, N'001419', N'Bảo vệ, cảnh vệ, cứu hỏa trong khu vực tổng kho xăng dầu quân sự.', N'IV', N'Tiếp xúc độc hại, nguy hiểm; căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10298, N'001420', N'Thử lực động cơ ô tô; thử bơm cao áp; thử xe ô tô đường dài; lái xe ô tô thử nghiệm quân sự.', N'IV', N'Nơi làm việc nóng, rất ồn, rung xóc liên tục.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10299, N'001421', N'Tẩy rửa Axít hàng quân sự.', N'IV', N'Thường xuyên tiếp xúc với hơi axit.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10300, N'001422', N'Thợ mộc phục vụ hàng quân sự', N'IV', N'Nơi làm việc nóng, ồn, bụi, thường xuyên tiếp xúc hoá dung môi hữu cơ, chất bảo quản.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10301, N'001423', N'Thợ sấy, tháo gỡ khuôn đúc hàng quân sự.', N'IV', N'Công việc nặng nhọc, tiếp xúc với nóng, bụi, hơi khí độc.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10302, N'001424', N'Pha chế thuốc phòng gỗ mục.', N'IV', N'Công việc thủ công, nặng nhọc, chịu tác động của hoá chất độc mạnh.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10303, N'001425', N'Gò tôn dày từ 1mm trở lên để lắp giáp (xe tăng, pháo).', N'IV', N'Công việc nặng nhọc, nóng, ảnh hưởng của bức xạ nhiệt, CO2 và ồn rất cao.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10304, N'001426', N'Ép doăng cao su, da, nhựa PVC, PA, PE thay thế các chi tiết súng, pháo.', N'IV', N'Công việc nặng nhọc, thường xuyên tiếp xúc với nóng, ồn, hoá chất độc.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10305, N'001427', N'Thợ vận hành trạm khí nén máy phát điện.', N'IV', N'Thường xuyên tiếp xúc với xăng dầu, chịu tác động của độ rung, tiếng ồn cao.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10306, N'001428', N'Vận hành dây chuyền sản xuất chất ÊtylBrômua phục vụ cho quân sự.', N'IV', N'Làm thủ công, tiếp xúc với hoá chất độc, bụi, ảnh hưởng tới hệ hô hấp.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10307, N'001429', N'Thợ sửa chữa trạm nguồn điện quân sự.', N'IV', N'Công việc nặng nhọc, độc hại, thường xuyên tiếp xúc với xăng dầu, hoá chất.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10308, N'001430', N'Kiểm định, KCS xe máy quân sự.', N'IV', N'Công việc nặng nhọc, thường xuyên làm việc trong điều kiện độc hại, nguy hiểm.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10309, N'001431', N'Thợ sửa chữa ô tô, tàu quân sự.', N'IV', N'Công việc nặng nhọc luôn tiếp xúc với dầu mỡ, tư thế gò bó, chịu tác động của tiếng ồn lớn.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10310, N'001432', N'Thủ kho quân y, bảo quản, cấp phát thuốc ở kho dự trữ chiến lược.', N'IV', N'Lao động trong môi trường kín, tiếp xúc trực tiếp với các loại hoá chất, gây căng thẳng thần kinh.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10311, N'001433', N'Nhân viên bảo mật làm việc trong phòng máy vi tính, máy phô tô.', N'IV', N'Thường xuyên làm việc trong phòng kín, tiếp xúc hơi khí độc, căng thẳng thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10312, N'001434', N'Xử lý và soạn tin tình báo, bảo mật trên máy vi tính.', N'IV', N'Cường độ lao động cao, căng thẳng thị lực, thần kinh tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10313, N'001435', N'Thợ sửa chữa điện, nước trong đơn vị quân đội.', N'IV', N'Tư thế làm việc gò bó, nguy hiểm.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10314, N'001436', N'Nhân viên hoá nghiệm phục vụ cho bảo quản hàng quân sự.', N'IV', N'Thường xuyên tiếp xúc với các hoá chất độc.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10315, N'001437', N'Phun xốp vào khoang giữa vách tàu chiến đấu.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc, nhiệt độ cao, tiếng ồn lớn.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10316, N'001438', N'Làm vệ sinh trong cơ quan, đơn vị quân đội.', N'IV', N'Lao động thủ công, thường xuyên tiếp xúc với chất thải hôi, thối.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10317, N'001439', N'Nhân viên quân y lấy mẫu, vận chuyển mẫu, làm xét nghiệm đối với các mầm bệnh (vi khuẩn, vi rút).', N'IV', N'Chịu tác động của các yếu tố độc hại, nguy hiểm của môi trường.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10318, N'001440', N'Nấu ăn tại các bếp ăn trong Quân đội.', N'IV', N'Công việc độc hại, nguy hiểm làm việc theo ca, chịu tác động của bụi, nóng.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10319, N'001441', N'Thủ kho, bảo quản cấp phát vật tư quân y ở kho cấp chiến dịch.', N'IV', N'Nơi làm việc kín, nóng, tiếp xúc trực tiếp với hoá chất.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10320, N'001442', N'Thợ sửa chữa ô tô, tàu và sửa chữa, sản xuất, đóng mới xuồng quân sự.', N'IV', N'Công việc nặng nhọc luôn tiếp xúc với dầu mỡ, tư thế gò bó, chịu tác động của tiếng ồn lớn.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10321, N'001443', N'Nhân viên khoa xét nghiệm tại bệnh viện hạng B tuyến quân khu, quân chủng.', N'IV', N'Thường xuyên tiếp xúc với hoá chất độc hại, mầm bệnh nguy hiểm.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10322, N'001444', N'Nuôi trồng hải sản ở Trường Sa, DK1.', N'IV', N'Thường xuyên làm việc nài trời, môi trường lao động ẩm ướt, chịu tác động của sóng, gió.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10323, N'001445', N'Thợ trạm khắc, sản xuất các loại con dấu phục vụ nhiệm vụ quân sự quốc phòng.', N'IV', N'Làm việc trong phòng kín, tiếp xúc với bụi, ồn.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10324, NULL, N'Lái xe phục vụ nghi lễ, tang lễ cấp Nhà nước.', N'IV', N'Công việc lưu động, nguy hiểm, nặng nhọc, chịu tác động của của ồn và rung, thực hiện nhiệm vụ trong điều kiện thường xuyên đi theo đoàn, áp lực, căng thẳng thị giác, thần kinh, áp lực bảo đảm an toàn giao thông, cự ly và tốc độ khi hành quân cơ giới.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10325, N'001447', N'Trưng cất EtylBrômua, sấy silycagen.', N'IV', N'Người lao động làm việc không theo giờ cố định. Công việc nặng nhọc, độc hại tiếp xúc với bụi, hoá chất, căng thẳng thị giác, thần kinh, tâm lý.', 9);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10326, N'001448', N'Làm thuốc bảo quản thi hài Chủ Tịch Hồ Chí Minh và thi thể thực nghiệm; vận hành, bảo quản, sửa chữa thiết bị kỹ thuật quan tài trong công trình lăng.', N'VI', N'Thường xuyên tiếp xúc hóa chất độc mạnh, làm việc dưới hầm ngầm, thiếu dưỡng khí, nhiệt độ thấp, rất căng thẳng thần kinh tâm lý.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10327, N'001449', N'Trực chỉ huy kỹ thuật, vận hành, bảo quản, sửa chữa, các hệ thống thiết bị kỹ thuật, kết cấu kiến trúc trong công trình lăng.', N'V', N'Làm việc dưới hầm ngầm, thiếu dưỡng khí, nhiệt độ thấp, tiếng ồn lớn, công việc đơn điệu, chịu ảnh hưởng điện từ trường.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10328, N'001450', N'Tiêu binh danh dự cửa lăng; tiêu binh danh dự thi hài.', N'V', N'Công việc đòi hỏi tập trung chú ý rất cao, tư thế gò bó, đơn điệu, mệt mỏi, căng thẳng thần kinh tâm lý.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10329, NULL, N'Bảo quản, sửa chữa kết cấu kiến trúc công trình lăng và các thiết bị kỹ thuật nài công trình.', N'IV', N'Làm việc nài trời công việc nặng nhọc.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10330, N'001452', N'Làm việc, bảo quản, sửa chữa thiết bị kiến trúc trong công trình ngầm dự phòng quốc phòng.', N'IV', N'Làm việc trong hầm ngầm, ẩm thấp, thiếu dưỡng khí, ánh sáng, công việc đơn điệu gò bó.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10331, N'001453', N'Gác vũ trang bảo đảm an ninh công trình lăng.', N'IV', N'Làm việc nài trời, công việc độc lập, nguy hiểm, căng thẳng thần kinh.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10332, NULL, N'Trực bảo đảm an ninh trong và nài công trình lăng.', N'IV', N'Làm việc trong hầm ngầm, thiếu dưỡng khi, công việc đơn điệu gò bó. Căng thẳng thần kinh tâm lý.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10333, NULL, N'Trực điều hành và trực tiếp làm nhiệm vụ đón tiếp tuyên truyền trong và nài công trình lăng.', N'IV', N'Thường xuyên làm việc nài trời nắng nóng, cường độ lao động cao, căng thẳng thần kinh tâm lý.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10334, N'001456', N'Cảnh vệ đặc biệt bảo vệ Lễ viếng Chủ tịch Hồ Chí Minh.', N'IV', N'Làm việc nơi chật hẹp, thiếu dưỡng khí, nhiệt độ trong công trình thấp, nhiệt độ nài trời cao.', 7);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10335, N'001457', N'Chụp ảnh địa hình trên không.', N'V', N'Nguy hiểm, chịu ảnh hưởng của thay đổi áp suất, nhiệt độ, tiếng ồn, rung xóc.', 8);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10336, N'001458', N'Đo đạc địa hình quân sự vùng rừng sâu, núi cao, hải đảo.', N'V', N'Làm việc nài trời, ở vùng nhiều đèo dốc, hiểm trở, công việc nặng nhọc, ảnh hưởng thị lực.', 8);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10337, N'001459', N'Chế bản đồ, mài bản kẽm, in bản đồ quân sự.', N'IV', N'Làm việc trong phòng kín, thiếu ánh sáng, dưỡng khí, tiếp xúc với bụi, ồn và hoá chất.', 8);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10338, N'001460', N'Bảo quản, tráng, rửa phim ảnh bản đồ quân sự.', N'IV', N'Làm việc trong phòng kín, thiếu ánh sáng, dưỡng khí, tiếp xúc với hoá chất độc hại.', 8);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10339, N'001461', N'Làm nhiệm vụ tuần tiễu trên tàu cao tốc.', N'VI', N'Công việc nặng nhọc, nguy hiểm, nơi làm việc chật hẹp, rung xóc, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10340, N'001462', N'Bộ đội các đồn biên phòng nơi đặc biệt khó khăn.', N'VI', N'Công việc nặng nhọc, gian khổ, đi lại khó khăn, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10341, N'001463', N'Phân giới cắm mốc, biên giới.', N'VI', N'Thường xuyên làm việc ở vùng núi cao, hiểm trở, đi lại khó khăn, thời tiết khắc nghiệt, nhiệm vụ phức tạp, nguy hiểm, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10342, N'001464', N'Phòng chống tội phạm ma tuý.', N'VI', N'Nhiệm vụ độc lập, luôn cơ động, phân tán, môi trường hoạt động độc hại, khó khăn, nguy hiểm, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10343, N'001465', N'Bộ đội biên phòng làm nhiệm vụ ở địa bàn được coi là đặc biệt khó khăn, gian khổ.', N'VI', N'Thường xuyên hoạt động trong điều kiện thời tiết khí hậu, môi trường độc hại, khó khăn, nguy hiểm, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10344, N'001466', N'Tuần tra trên biển của các Hải Đoàn, Hải Đội thuộc Bộ đội Biên phòng.', N'VI', N'Thường xuyên chịu tác động của sóng, gió, rung, xóc lớn, công việc nặng nhọc, rất nguy hiểm, nơi làm việc chật hẹp, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10345, N'001467', N'Chăn nuôi, huấn luyện và sử dụng chó nghiệp vụ.', N'VI', N'Công việc nặng nhọc, độc hại, nguy hiểm, căng thẳng, dễ gây nhiễm bệnh.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10346, N'001468', N'Tuần tra trên biển.', N'V', N'Nơi làm việc chật hẹp, chịu tác động sóng gió, rung xóc, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10347, N'001469', N'Trinh sát biên phòng, bộ đội ở các đồn biên phòng vùng rừng sâu, núi cao và đảo xa.', N'V', N'Công việc nặng nhọc, độc lập nơi địa hình phức tạp, khó khăn, căng thẳng thần kinh tâm lý.', 6);
INSERT INTO dm.nghe (id,ma, ten,loai_nghe,dien_giai,nganh_id) VALUES (10348, N'001470', N'Nuôi và huấn luyện chó nghiệp vụ.', N'V', N'Công việc nặng nhọc, phức tạp, nguy hiểm, dễ nhiễm bệnh.', 6);
